return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=1; plural=0;','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'ໄປທີ່ Plugin Search','Activate %s' => 'ເປີດໃຊ້ %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> ຕ້ອງການ <strong>%2$s</strong> ເພື່ອຕິດຕັ້ງ ແລະເປີດໃຊ້ງານ. <a href="%4$s">%3$s</a>','Enter your code here' => 'ໃສ່ລະຫັດຂອງເຈົ້າທີ່ນີ້','Add %s' => 'ເພີ່ມ %s','Remove' => 'ເອົາອອກ','Order number and receipt will be sent to this email address.' => 'ໝາຍເລກການສັ່ງຊື້ ແລະໃບຮັບເງິນຈະຖືກສົ່ງໄປທີ່ທີ່ຢູ່ອີເມວນີ້.','Apartment, unit, building, floor, etc.' => 'ອາພາດເມັນ, ຫນ່ວຍງານ, ອາຄານ, ຊັ້ນ, ແລະອື່ນໆ.','Shipping phone' => 'ໂທລະສັບຂົນສົ່ງ','Only used for shipping-related questions.' => 'ໃຊ້ສໍາລັບຄໍາຖາມທີ່ກ່ຽວຂ້ອງກັບການຂົນສົ່ງເທົ່ານັ້ນ.','Single step' => 'ຂັ້ນຕອນດຽວ','Click to go to the order summary' => 'ຄລິກເພື່ອໄປທີ່ສະຫຼຸບການສັ່ງຊື້','Cart total:' => 'ທັງໝົດກະຕ່າ:','Proceed to %s' => 'ສືບຕໍ່ໄປຫາ %s','Proceed to contact' => 'ດໍາເນີນການຕິດຕໍ່','Proceed to shipping' => 'ສືບຕໍ່ການຂົນສົ່ງ','Proceed to billing' => 'ສືບຕໍ່ການຮຽກເກັບເງິນ','Proceed to payment' => 'ດໍາເນີນການຊໍາລະ','Shipping method' => 'ວິທີການຂົນສົ່ງ','Additional notes' => 'ບັນທຶກເພີ່ມເຕີມ','Payment method' => 'ວິທີການຈ່າຍເງິນ','Step %1$s of %2$s' => 'ຂັ້ນຕອນ %1$s ຂອງ %2$s','Change: %s' => 'ປ່ຽນແປງ: %s','Not selected yet.' => 'ຍັງບໍ່ໄດ້ເລືອກເທື່ອ.','Same as shipping address' => 'ຄືກັນກັບທີ່ຢູ່ຈັດສົ່ງ','Same as billing address' => 'ຄືກັນກັບທີ່ຢູ່ໃບບິນ','Order summary' => 'ສະຫຼຸບການສັ່ງ','Edit cart' => 'ແກ້ໄຂກະຕ່າ','Did you mean %s?' => 'ເຈົ້າໝາຍເຖິງ %s ບໍ?','Change email address to: {suggestion-value}' => 'ປ່ຽນທີ່ຢູ່ອີເມວເປັນ: {suggestion-value}','This is a required field.' => 'ນີ້ແມ່ນຊ່ອງຂໍ້ມູນທີ່ຕ້ອງການ.','This is not a valid email address.' => 'ນີ້ບໍ່ແມ່ນທີ່ຢູ່ອີເມວທີ່ຖືກຕ້ອງ.','This field does not match the related field value.' => 'ຊ່ອງຂໍ້ມູນນີ້ບໍ່ກົງກັບຄ່າຊ່ອງຂໍ້ມູນທີ່ກ່ຽວຂ້ອງ.','The CPF number "{cpf_number}" is invalid.' => 'ໝາຍເລກ CPF &quot;{cpf_number}&quot; ບໍ່ຖືກຕ້ອງ.','The CNPJ number "{cnpj_number}" is invalid.' => 'ໝາຍເລກ CNPJ &quot;{cnpj_number}&quot; ບໍ່ຖືກຕ້ອງ.','(Required)' => '(ຕ້ອງການ)','Checkout Header - Desktop' => 'Checkout Header - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'ສະແດງ widget ໃນສ່ວນຫົວການຈ່າຍເງິນສໍາລັບຫນ້າຈໍຂະຫນາດໃຫຍ່. ສະແດງພຽງແຕ່ຖ້າໃຊ້ສ່ວນຫົວການຈ່າຍເງິນຂອງປລັກອິນ.','Checkout Header - Mobile' => 'Checkout Header - ມືຖື','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'ສະ​ແດງ widget ຢູ່​ລຸ່ມ​ຫົວ​ຂໍ້​ການ​ຊໍາ​ລະ​ເງິນ​ສໍາ​ລັບ​ອຸ​ປະ​ກອນ​ມື​ຖື​. ສະແດງພຽງແຕ່ຖ້າໃຊ້ສ່ວນຫົວການຈ່າຍເງິນຂອງປລັກອິນ.','Checkout Sidebar' => 'Checkout Sidebar','Display widgets on the checkout sidebar after the order summary.' => 'ສະແດງ widget ໃນແຖບດ້ານຂ້າງການຈ່າຍເງິນຫຼັງຈາກສະຫຼຸບການສັ່ງຊື້.','Checkout Order Summary' => 'ສະຫຼຸບການສັ່ງຈ່າຍເງິນ','Display widgets inside the order summary at the checkout page.' => 'ສະແດງ widget ພາຍໃນບົດສະຫຼຸບການສັ່ງຊື້ຢູ່ຫນ້າຈ່າຍເງິນ.','Checkout Below Place Order' => 'ກວດ​ສອບ​ການ​ສັ່ງ​ຊື້​ຢູ່​ລຸ່ມ​ນີ້​','Display widgets below the place order button at the checkout page.' => 'ສະ​ແດງ widget ຢູ່​ລຸ່ມ​ປຸ່ມ​ສັ່ງ​ສະ​ຖານ​ທີ່​ຢູ່​ໃນ​ຫນ້າ​ຊໍາ​ລະ​ເງິນ.','Checkout Footer' => 'ສ່ວນທ້າຍການຈ່າຍເງິນ','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'ສະແດງ widget ໃນສ່ວນທ້າຍການຈ່າຍເງິນ. ສະແດງພຽງແຕ່ຖ້າໃຊ້ສ່ວນທ້າຍການຈ່າຍເງິນຂອງ plugin.','Classic' => 'ຄລາສິກ','Boxed' => 'ກ່ອງ','Split' => 'ແຍກ','Minimalist' => 'ຫນ້ອຍ','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'ປັ໊ກອິນການແຈ້ງອອກຂອງແຫຼວ ແລະວັນທີຈັດສົ່ງໂດຍ CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>ພວກເຮົາກວດພົບວ່າທ່ານກໍາລັງໃຊ້ plugins Delivery &amp; Pickup Date Time ສໍາລັບ WooCommerce (ຟຣີ ແລະ PRO) ໂດຍ CodeRockz. ການປະສົມປະສານກັບປລັກອິນເຫຼົ່ານີ້ໄດ້ຖືກຍ້າຍໄປ Fluid Checkout PRO.</p>','Upgrade to PRO' => 'ອັບເກຣດເປັນ PRO','Fluid Checkout database updated successfully' => 'ອັບເດດຖານຂໍ້ມູນ Fluid Checkout ສຳເລັດແລ້ວ','The database changes where applied successfully.' => 'ຖານຂໍ້ມູນມີການປ່ຽນແປງບ່ອນທີ່ນໍາໃຊ້ຢ່າງສໍາເລັດຜົນ.','Dismiss' => 'ປິດ','Fluid Checkout database update' => 'ອັບເດດຖານຂໍ້ມູນ Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ບາງການປ່ຽນແປງໃນຖານຂໍ້ມູນແມ່ນຕ້ອງການ. ເຊັ່ນດຽວກັນກັບການປັບປຸງໃດໆ, ພວກເຮົາແນະນໍາໃຫ້ທ່ານ <strong>ເຮັດການສໍາຮອງຂໍ້ມູນຢ່າງເຕັມທີ່ຂອງເວັບໄຊທ໌ຂອງເຈົ້າກ່ອນທີ່ຈະດໍາເນີນການ</strong> .','Update database' => 'ອັບເດດຖານຂໍ້ມູນ','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout ບໍ່ເຂົ້າກັນໄດ້ກັບຮູບແບບການເຊັກເອົາ Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout ຕ້ອງການແບບຟອມຊໍາລະທີ່ອີງໃສ່ WooCommerce shortcode ຄລາສສິກເພື່ອເຮັດວຽກ. ເມື່ອໃຊ້ Divi Builder ເພື່ອປັບແຕ່ງລັກສະນະແລະຄວາມຮູ້ສຶກຂອງຫນ້າເຊັກເອົາ, shortcodes ຄລາສສິກຖືກແທນທີ່ດ້ວຍ widget ທີ່ກໍາຫນົດເອງຈາກ Divi Builder ສໍາລັບແຕ່ລະສ່ວນຂອງຫນ້າ checkout. widget ແບບກຳນົດເອງເຫຼົ່ານີ້ບໍ່ເຂົ້າກັນໄດ້ກັບ Fluid Checkout.</p><p> ກະລຸນາແກ້ໄຂໜ້າຈ່າຍເງິນຂອງທ່ານແທນວິດເຈັດ Divi Builder ດ້ວຍ widget ຂໍ້ຄວາມທີ່ມີ shortcode <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'ແກ້ໄຂໜ້າຈ່າຍເງິນ','Read the documentation.' => 'ອ່ານເອກະສານ.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'ຄຸນສົມບັດການກວດສອບຫຼາຍຂັ້ນຕອນຂອງ Germanized PRO ຈໍາເປັນຕ້ອງຖືກປິດໃຊ້ງານໃນເວລາໃຊ້ Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'ເມື່ອໃຊ້ Fluid Checkout, ຄຸນສົມບັດ multistep ຈາກ plugin Germanized PRO ກາຍເປັນສິ່ງທີ່ບໍ່ຈໍາເປັນແລະສາມາດເຮັດໃຫ້ເກີດ <strong>ຄວາມຜິດພາດທີ່ສໍາຄັນໃນຂະນະທີ່ດໍາເນີນການຄໍາສັ່ງໃຫມ່</strong> . ກະລຸນາປິດຄຸນສົມບັດການຊໍາລະອອກຫຼາຍຂັ້ນຕອນຂອງ Germanized PRO ໃນການຕັ້ງຄ່າປລັກອິນ.','Go to Germanized settings' => 'ໄປທີ່ການຕັ້ງຄ່າ Germanized','Thanks for choosing Fluid Checkout!' => 'ຂອບໃຈທີ່ເລືອກ Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'ທ່ານໄດ້ໃຊ້ plugin ສໍາລັບໃນຂະນະທີ່ໃນປັດຈຸບັນ. ເຈົ້າມັກມັນແນວໃດມາເຖິງຕອນນັ້ນ?<br> ກະ​ລຸ​ນາ​ໃຫ້​ພວກ​ເຮົາ​ໃຫ້​ຄະ​ແນນ​ໄວ​, ພວກ​ເຮົາ​ຂໍ​ຂອບ​ໃຈ​ທຸກ​ຄໍາ​ຄຶດ​ຄໍາ​ເຫັນ​ແລະ​ມັນ​ຊຸກ​ຍູ້​ໃຫ້​ພວກ​ເຮົາ​ສືບ​ຕໍ່​ປັບ​ປຸງ plugin :)','Rate the plugin' => 'ໃຫ້ຄະແນນ plugin','I need help!' => 'ຂ້ອຍຕ້ອງການຄວາມຊ່ວຍເຫຼືອ!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'ຄຸນສົມບັດບາງຢ່າງຂອງ WooCommerce Checkout Manager ໂດຍ Quadlayers ອາດຈະບໍ່ເຮັດວຽກຕາມທີ່ຄາດໄວ້ເມື່ອໃຊ້ມັນກັບ Fluid Checkout. ອ່ານ <a href="%s">ເອກະສານຂອງພວກເຮົາ</a> ສໍາລັບຂໍ້ມູນເພີ່ມເຕີມແລະວິທີແກ້ໄຂທາງເລືອກ.','Read documentation' => 'ອ່ານເອກະສານ','Don\'t show this again' => 'ຢ່າສະແດງອັນນີ້ອີກ','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'ແມ່ແບບການອອກແບບເພີ່ມເຕີມ','Optimized cart page' => 'ຫນ້າໂຄງຮ່າງການທີ່ດີທີ່ສຸດ','Optimized order received / thank you page' => 'ໄດ້ຮັບຄໍາສັ່ງທີ່ດີທີ່ສຸດ / ຂອບໃຈຫນ້າ','Edit cart contents at checkout page' => 'ແກ້ໄຂເນື້ອໃນກະຕ່າຢູ່ໜ້າຈ່າຍເງິນ','Account matching / user matching' => 'ການຈັບຄູ່ບັນຊີ / ການຈັບຄູ່ຜູ້ໃຊ້','Trust symbols on the cart and thank you pages' => 'ສັນຍາລັກຄວາມໄວ້ວາງໃຈໃນໂຄງຮ່າງການແລະຫນ້າຂອບໃຈ','More positions for the coupon code on the checkout page' => 'ຕໍາແຫນ່ງເພີ່ມເຕີມສໍາລັບລະຫັດຄູປອງໃນຫນ້າຈ່າຍເງິນ','International phone numbers' => 'ເບີໂທລະສັບສາກົນ','Gift messages and packing slips' => 'ຂໍ້ຄວາມຂອງຂວັນ ແລະໃບເກັບເງິນ','Local pickup and in-store collection' => 'ການໄປຮັບໃນທ້ອງຖິ່ນ ແລະ ການເກັບໃນຮ້ານ','EU-VAT Assistant' => 'ຜູ້ຊ່ວຍ EU-VAT','I already have it – Hide this offer' => 'ຂ້ອຍມີມັນແລ້ວ - ເຊື່ອງຂໍ້ສະເໜີນີ້','Activated' => 'ເປີດໃຊ້ແລ້ວ','Address book' => 'ປື້ມທີ່ຢູ່','Select an image' => 'ເລືອກຮູບ','Cart layout' => 'ຮູບແບບໂຄງຮ່າງການ','Cart optimizations' => 'ການປັບແຕ່ງໂຄງຮ່າງການ','Enable cart page optimizations' => 'ເປີດໃຊ້ການປັບແຕ່ງໜ້າກະຕ່າ','Header and footer template' => 'ແມ່ແບບສ່ວນຫົວ ແລະສ່ວນທ້າຍ','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'ຄວບຄຸມວ່າຈະໃຊ້ສ່ວນຫົວ ແລະສ່ວນທ້າຍຂອງໜ້າທີ່ບໍ່ມີການລົບກວນ ຫຼືຮັກສາສ່ວນຫົວ ແລະສ່ວນທ້າຍຂອງຮູບແບບສີສັນທີ່ນຳໃຊ້ຢູ່ໃນປັດຈຸບັນ.','Distraction free header and footer' => 'ສ່ວນຫົວ ແລະສ່ວນທ້າຍບໍ່ມີສິ່ງລົບກວນ','Theme\'s header and footer' => 'ສ່ວນຫົວ ແລະສ່ວນທ້າຍຂອງຫົວຂໍ້','Cart elements' => 'ອົງປະກອບຂອງໂຄງຮ່າງການ','Make the order summary stay visible on the cart page while scrolling' => 'ເຮັດໃຫ້ສະຫຼຸບການສັ່ງຊື້ຢູ່ໃນຫນ້າກະຕ່າໃນຂະນະທີ່ເລື່ອນ','Coupon codes' => 'ລະຫັດຄູປອງ','Hidden' => 'ເຊື່ອງໄວ້','Before the cart items section' => 'ກ່ອນທີ່ຈະພາກສ່ວນລາຍການໂຄງຮ່າງການ','Inside the cart items section' => 'ພາຍໃນພາກສ່ວນລາຍການກະຕ່າ','After the cart items section' => 'ຫຼັງຈາກພາກສ່ວນລາຍການໂຄງຮ່າງການ','Before the shipping section' => 'ກ່ອນພາກສ່ວນການຂົນສົ່ງ','After the shipping section' => 'ຫຼັງຈາກພາກສ່ວນການຂົນສົ່ງ','Before the order summary' => 'ກ່ອນທີ່ຈະສະຫຼຸບຄໍາສັ່ງ','Inside the order summary' => 'ພາຍໃນສະຫຼຸບຄໍາສັ່ງ','Before the order totals' => 'ກ່ອນທີ່ຈະມີຄໍາສັ່ງທັງຫມົດ','After the order totals' => 'ຫຼັງຈາກຄໍາສັ່ງທັງຫມົດ','After the order summary' => 'ຫຼັງຈາກສະຫຼຸບຄໍາສັ່ງ','Shipping' => 'ການຂົນສົ່ງ','Select position where to display the shipping costs and calculator on the cart page.' => 'ເລືອກຕຳແໜ່ງບ່ອນທີ່ຈະສະແດງຄ່າຂົນສົ່ງ ແລະເຄື່ອງຄິດເລກໃນໜ້າກະຕ່າ.','Display as a cart section' => 'ສະແດງເປັນພາກສ່ວນກະຕ່າ','Cross-sells' => 'ຂາຍຂ້າມ','Select position where to display the cross-sells section on the cart page.' => 'ເລືອກຕໍາແຫນ່ງທີ່ຈະສະແດງພາກສ່ວນການຂາຍຂ້າມໃນຫນ້າໂຄງຮ່າງການ.','Before the cart actions' => 'ກ່ອນທີ່ຈະປະຕິບັດໂຄງຮ່າງການ','After the cart actions' => 'ຫຼັງຈາກການປະຕິບັດໂຄງຮ່າງການ','Layout of cross-sell items on the cart page.' => 'ຮູບແບບຂອງສິນຄ້າຂ້າມຂາຍໃນໜ້າກະຕ່າ.','Optimized horizontal cross-sells layout' => 'ການຈັດວາງການຂາຍຂ້າມແນວນອນທີ່ເໝາະສົມແລ້ວ','Theme\'s cross-sells layout' => 'ຮູບແບບການຂາຍຂ້າມຂອງຫົວຂໍ້','Number of cross-sell items to display on the cart page' => 'ຈໍາ​ນວນ​ຂອງ​ລາຍ​ການ​ຂາຍ​ຂ້າມ​ທີ່​ຈະ​ສະ​ແດງ​ຢູ່​ໃນ​ຫນ້າ​ໂຄງ​ຮ່າງ​ການ​','Add widget areas to the cart page' => 'ເພີ່ມພື້ນທີ່ widget ໃສ່ໜ້າກະຕ່າ','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'ພື້ນທີ່ widget ເຫຼົ່ານີ້ຖືກນໍາໃຊ້ເພື່ອເພີ່ມສັນຍາລັກຄວາມໄວ້ວາງໃຈແລະປ້າຍຄວາມໄວ້ວາງໃຈໃນຫນ້າໂຄງຮ່າງການ.','Checkout' => 'ຈ່າຍເງິນ','Checkout layout' => 'ຮູບ​ແບບ​ການ​ຊໍາ​ລະ​ເງິນ​','Design template' => 'ອອກແບບແມ່ແບບ','Dark mode' => 'ໂໝດມືດ','Enable dark mode' => 'ເປີດໃຊ້ໂໝດມືດ','Logo image' => 'ຮູບໂລໂກ້','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'ເລືອກຮູບທີ່ຈະສະແດງຢູ່ໃນສ່ວນຫົວຂອງໜ້າຈ່າຍເງິນ. ນຳໃຊ້ສະເພາະເມື່ອໃຊ້ສ່ວນຫົວ ແລະສ່ວນທ້າຍທີ່ບໍ່ມີການລົບກວນ.','Header background color' => 'ສີພື້ນຫຼັງສ່ວນຫົວ','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ເລືອກສີພື້ນຫຼັງສຳລັບສ່ວນຫົວຂອງໜ້າຈ່າຍເງິນ. ນຳໃຊ້ສະເພາະເມື່ອໃຊ້ສ່ວນຫົວ ແລະສ່ວນທ້າຍທີ່ບໍ່ມີການລົບກວນ.','HTML color value. ie: #f3f3f3' => 'ຄ່າສີ HTML. ເຊັ່ນ: #f3f3f3','Page background color' => 'ສີພື້ນຫຼັງຂອງໜ້າ','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ເລືອກສີພື້ນຫຼັງສຳລັບໜ້າຈ່າຍເງິນ. ສີຖືກນໍາໃຊ້ກັບອົງປະກອບ <em>ຂອງຮ່າງກາຍ</em> .','Footer background color' => 'ສີພື້ນຫຼັງສ່ວນທ້າຍ','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ເລືອກສີພື້ນຫຼັງສຳລັບສ່ວນທ້າຍໜ້າການຈ່າຍເງິນ. ນຳໃຊ້ສະເພາະເມື່ອໃຊ້ສ່ວນຫົວ ແລະສ່ວນທ້າຍທີ່ບໍ່ມີການລົບກວນ.','Progress bar' => 'ແຖບຄວາມຄືບຫນ້າ','Display the checkout progress bar when using multi-step checkout layout' => 'ສະແດງແຖບຄວາມຄືບໜ້າການຊຳລະເງິນເມື່ອໃຊ້ຮູບແບບການຈ່າຍເງິນຫຼາຍຂັ້ນຕອນ','Make the checkout progress bar stay visible while scrolling' => 'ເຮັດໃຫ້ແຖບຄວາມຄືບໜ້າການຊຳລະເງິນຢູ່ເຫັນໄດ້ໃນຂະນະທີ່ເລື່ອນ','Express checkout' => 'ຈ່າຍເງິນດ່ວນ','Enable the express checkout section' => 'ເປີດໃຊ້ພາກສ່ວນຈ່າຍເງິນດ່ວນ','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'ສະແດງພາກສ່ວນການຈ່າຍເງິນດ່ວນໃນເວລາຈ່າຍເງິນເມື່ອປະຕູການຈ່າຍເງິນທີ່ຮອງຮັບໄດ້ເປີດໃຊ້ຄຸນສົມບັດນີ້.','Display express checkout buttons in one line for larger screens' => 'ສະແດງປຸ່ມຈ່າຍເງິນດ່ວນໃນແຖວດຽວສຳລັບໜ້າຈໍໃຫຍ່','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'ບໍ່ສົນໃຈຊ່ອງທີ່ຕ້ອງຈ່າຍເງິນເພີ່ມເຕີມເມື່ອຈ່າຍເງິນດ້ວຍປະຕູການຈ່າຍເງິນດ່ວນທີ່ເຂົ້າກັນໄດ້','Make the order summary stay visible while scrolling' => 'ເຮັດໃຫ້ການສັງລວມຄໍາສັ່ງສາມາດເຫັນໄດ້ໃນຂະນະທີ່ເລື່ອນ','Choose a background color for the order summary section.' => 'ເລືອກສີພື້ນຫຼັງສຳລັບພາກສ່ວນສະຫຼຸບຄຳສັ່ງຊື້.','Highlight the order totals row in the order summary table' => 'ເນັ້ນໃສ່ແຖວທັງໝົດຂອງຄໍາສັ່ງໃນຕາຕະລາງສະຫຼຸບຄໍາສັ່ງ','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'ເປັນປະໂຫຍດທີ່ສຸດໃນເວລາທີ່ພາກສ່ວນສະຫຼຸບຄໍາສັ່ງບໍ່ມີສີພື້ນຫລັງທີ່ເນັ້ນ. ອາດຈະນຳໃຊ້ກັບໂຄງຮ່າງການ, ໃບສັ່ງທີ່ໄດ້ຮັບ ແລະເບິ່ງໜ້າການສັ່ງຊື້ໃນເວລານຳໃຊ້ Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'ການເຊື່ອມໂຍງການປະຕິບັດກ່ຽວກັບການສະຫຼຸບຄໍາສັ່ງໃນເວລາຈ່າຍເງິນ.','Edit cart link' => 'ແກ້ໄຂລິ້ງກະຕ່າ','Cart items count' => 'ນັບລາຍການກະຕ່າ','Link to shop page' => 'ລິ້ງໄປຫາໜ້າຮ້ານ','Cart items' => 'ລາຍການກະຕ່າ','Hide cart items errors at the checkout page' => 'ເຊື່ອງຄວາມຜິດພາດລາຍການກະຕ່າຢູ່ໜ້າຈ່າຍເງິນ','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'ຢ່າສະແດງຂໍ້ຄວາມຜິດພາດຂອງລາຍການລົດເຂັນຢູ່ເທິງສຸດຂອງໜ້າຈ່າຍເງິນ. ເມື່ອສົ່ງແບບຟອມຈ່າຍເງິນເພື່ອເຮັດສໍາເລັດການຊື້, ຂໍ້ຄວາມສະແດງຂໍ້ຜິດພາດເຫຼົ່ານີ້ຈະຖືກສະແດງຢູ່ສະເຫມີ.','Place order' => 'ວາງຄໍາສັ່ງ','Define the position to display "Place order" and terms checkbox section.' => 'ກໍາ​ນົດ​ຕໍາ​ແຫນ່ງ​ທີ່​ຈະ​ສະ​ແດງ &quot;ຄໍາ​ສັ່ງ​ສະ​ຖານ​ທີ່​&quot; ແລະ​ພາກ​ສ່ວນ checkbox ຂໍ້​ກໍາ​ນົດ​.','Some options might not be compatible with some plugins and themes.' => 'ບາງທາງເລືອກອາດຈະບໍ່ເຂົ້າກັນໄດ້ກັບບາງປລັກອິນ ແລະຮູບແບບສີສັນ.','Below the payment section' => 'ຂ້າງລຸ່ມນີ້ພາກສ່ວນການຈ່າຍເງິນ','Below the order summary' => 'ຂ້າງລຸ່ມນີ້ສະຫຼຸບຄໍາສັ່ງ','Both below the payment section and the order summary' => 'ທັງຢູ່ຂ້າງລຸ່ມພາກສ່ວນການຈ່າຍເງິນ ແລະບົດສະຫຼຸບການສັ່ງຊື້','Add widget areas to the checkout page' => 'ເພີ່ມພື້ນທີ່ widget ໃສ່ໜ້າຈ່າຍເງິນ','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'ພື້ນທີ່ widget ເຫຼົ່ານີ້ຖືກນໍາໃຊ້ເພື່ອເພີ່ມສັນຍາລັກຄວາມໄວ້ວາງໃຈແລະປ້າຍຄວາມໄວ້ວາງໃຈໃນຫນ້າຈ່າຍເງິນ.','Display the coupon codes section title' => 'ສະແດງຫົວຂໍ້ລະຫັດຄູປອງ','Select position where to display the coupon codes section on the checkout page.' => 'ເລືອກຕຳແໜ່ງບ່ອນທີ່ຈະສະແດງສ່ວນລະຫັດຄູປ໋ອງຢູ່ໃນໜ້າຈ່າຍເງິນ.','Before the checkout steps' => 'ກ່ອນຂັ້ນຕອນການຈ່າຍເງິນ','As a substep before payment methods' => 'ເປັນຂັ້ນຕອນຍ່ອຍກ່ອນວິທີການຊໍາລະ','As a substep after payment methods' => 'ເປັນຂັ້ນຕອນຍ່ອຍຫຼັງຈາກວິທີການຊໍາລະ','Default button style' => 'ຮູບແບບປຸ່ມເລີ່ມຕົ້ນ','"Add" link button' => 'ປຸ່ມເຊື່ອມຕໍ່ &quot;ເພີ່ມ&quot;.','Checkout fields' => 'ຊ່ອງຈ່າຍເງິນ','Optional fields' => 'ຊ່ອງຂໍ້ມູນທາງເລືອກ','Hide optional fields behind a link button' => 'ເຊື່ອງຊ່ອງຂໍ້ມູນທາງເລືອກທີ່ຢູ່ເບື້ອງຫຼັງປຸ່ມເຊື່ອມຕໍ່','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'ມັນ​ໄດ້​ຖືກ​ແນະ​ນໍາ​ໃຫ້​ຮັກ​ສາ​ທາງ​ເລືອກ​ນີ້​ກວດ​ກາ​ເພື່ອ​ຫຼຸດ​ຜ່ອນ​ຈໍາ​ນວນ​ຂອງ​ການ​ປ້ອນ​ຂໍ້​ມູນ​ເປີດ​, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">ອ່ານ​ການ​ຄົ້ນ​ຄວ້າ</a> ​.','Do not hide "Address line 2" fields behind a link button' => 'ຢ່າເຊື່ອງຊ່ອງຂໍ້ມູນ &quot;ທີ່ຢູ່ແຖວ 2&quot; ທີ່ຢູ່ເບື້ອງຫຼັງປຸ່ມເຊື່ອມຕໍ່','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'ແນະນໍາພຽງແຕ່ໃນເວລາທີ່ລູກຄ້າສ່ວນໃຫຍ່ຕ້ອງການພາກສະຫນາມ &quot;ທີ່ຢູ່ແຖວ 2&quot;, ຫຼືເມື່ອໄດ້ຮັບທີ່ຢູ່ການຂົນສົ່ງທີ່ຖືກຕ້ອງແມ່ນສໍາຄັນ (ເຊັ່ນ: ຖ້າການຈັດສົ່ງອາຫານແລະຜະລິດຕະພັນທີ່ເສຍຫາຍອື່ນໆ).','Billing address' => 'ທີ່ຢູ່ໃບບິນ','Select position where to display the billing address section on the checkout page.' => 'ເລືອກຕຳແໜ່ງບ່ອນທີ່ຈະສະແດງພາກສ່ວນທີ່ຢູ່ໃບບິນໃນໜ້າຈ່າຍເງິນ.','As a step before shipping' => 'ເປັນຂັ້ນຕອນກ່ອນການຂົນສົ່ງ','As a sub-step before the shipping address section' => 'ເປັນຂັ້ນຕອນຍ່ອຍກ່ອນພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງ','As a sub-step after the shipping address section' => 'ເປັນຂັ້ນຕອນຍ່ອຍຫຼັງຈາກພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງ','As a step after shipping' => 'ເປັນຂັ້ນຕອນຫຼັງຈາກການຂົນສົ່ງ','As a sub-step before the payment section' => 'ເປັນຂັ້ນຕອນຍ່ອຍກ່ອນພາກສ່ວນການຈ່າຍເງິນ','Force billing and shipping addresses to the same (single section)' => 'ບັງຄັບໃຫ້ໃບບິນ ແລະທີ່ຢູ່ຈັດສົ່ງເປັນອັນດຽວກັນ (ພາກສ່ວນດຽວ)','Checkbox for "Same as shipping/billing address" checked by default' => 'ກ່ອງໝາຍສຳລັບ &quot;ຄືກັນກັບທີ່ຢູ່ສົ່ງ/ໃບບິນ&quot; ຖືກໝາຍໄວ້ຕາມຄ່າເລີ່ມຕົ້ນ','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'ກ່ອງກາໝາຍ &quot;ຄືກັນກັບທີ່ຢູ່ຈັດສົ່ງ&quot; ຈະເລີ່ມເປັນໝາຍຖືກຕາມຄ່າເລີ່ມຕົ້ນເມື່ອພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງຈະສະແດງກ່ອນ.<br> ກ່ອງກາໝາຍ &quot;ຄືກັນກັບທີ່ຢູ່ໃບບິນ&quot; ຈະເລີ່ມເປັນໝາຍຖືກຕາມຄ່າເລີ່ມຕົ້ນ ເມື່ອພາກສ່ວນທີ່ຢູ່ໃບບິນຖືກສະແດງກ່ອນ.<br> ມັນໄດ້ຖືກແນະນໍາໃຫ້ອອກຈາກທາງເລືອກນີ້ກວດເບິ່ງເປັນການຫຼຸດຜ່ອນຢ່າງຫຼວງຫຼາຍຂອງຊ່ອງປ້ອນຂໍ້ມູນເປີດຢູ່ checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">ອ່ານການຄົ້ນຄວ້າ</a> .','Highlight the billing address section in the checkout form' => 'ເນັ້ນໃສ່ພາກສ່ວນທີ່ຢູ່ໃບບິນໃນແບບຟອມຈ່າຍເງິນ','Shipping address' => 'ທີ່ຢູ່ສົ່ງ','Highlight the shipping address section in the checkout form' => 'ເນັ້ນໃສ່ພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງໃນແບບຟອມຈ່າຍເງິນ','Shipping methods' => 'ວິທີການຂົນສົ່ງ','Choose in which position to display the shipping methods section.' => 'ເລືອກຢູ່ໃນຕໍາແຫນ່ງໃດທີ່ຈະສະແດງພາກສ່ວນວິທີການຂົນສົ່ງ.','Before shipping address' => 'ກ່ອນການຈັດສົ່ງທີ່ຢູ່','After shipping address' => 'ຫຼັງຈາກທີ່ຢູ່ຈັດສົ່ງ','Local pickup' => 'ໄປຮັບທ້ອງຖິ່ນ','Removes shipping address section when a local pickup shipping method is selected.' => 'ເອົາພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງອອກເມື່ອເລືອກວິທີການຈັດສົ່ງໃນທ້ອງຖິ່ນ.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'ແທນທີ່ທີ່ຢູ່ຈັດສົ່ງດ້ວຍສະຖານທີ່ຈຸດຮັບເມື່ອເລືອກວິທີການຈັດສົ່ງໃນທ້ອງຖິ່ນ.','Choose which address to save as the shipping address for local pickup orders.' => 'ເລືອກທີ່ຢູ່ທີ່ຈະບັນທຶກເປັນທີ່ຢູ່ສົ່ງສໍາລັບຄໍາສັ່ງໄປຮັບໃນທ້ອງຖິ່ນ.','Save the selected pickup location' => 'ບັນທຶກສະຖານທີ່ຮັບທີ່ເລືອກ','Save same as the billing address' => 'ບັນທຶກຄືກັນກັບທີ່ຢູ່ໃບບິນ','Do not save any shipping address' => 'ຢ່າບັນທຶກທີ່ຢູ່ຈັດສົ່ງໃດໆ','Company name field for shipping address' => 'ຊ່ອງຂໍ້ມູນຊື່ບໍລິສັດສຳລັບທີ່ຢູ່ຈັດສົ່ງ','Change visibility for the company name field for the shipping address section on the checkout form.' => 'ປ່ຽນການເບິ່ງເຫັນສໍາລັບຊ່ອງຂໍ້ມູນຊື່ບໍລິສັດສໍາລັບພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງໃນແບບຟອມເຊັກເອົາ.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'ຖ້າຊ່ອງຂໍ້ມູນຖືກຕັ້ງເປັນ &quot;ທາງເລືອກ&quot;, ເຊິ່ງເປັນສະຖານະເລີ່ມຕົ້ນຂອງການເບິ່ງເຫັນ, ບໍ່ມີການປ່ຽນແປງໃດໆທີ່ຈະຖືກນໍາໃຊ້ເພື່ອໃຫ້ plugins ອື່ນໆນໍາໃຊ້ການປ່ຽນແປງທີ່ພວກເຂົາຕ້ອງການ.','Hidden (remove field)' => 'ເຊື່ອງໄວ້ (ເອົາຊ່ອງຂໍ້ມູນອອກ)','Optional' => 'ທາງເລືອກ','Required' => 'ຕ້ອງການ','Add shipping phone field to the checkout form.' => 'ເພີ່ມຊ່ອງໃສ່ໂທລະສັບໃນການຂົນສົ່ງໃສ່ແບບຟອມຈ່າຍເງິນ.','Choose in which step to display the shipping phone field.' => 'ເລືອກໃນຂັ້ນຕອນໃດເພື່ອສະແດງຊ່ອງໂທລະສັບຂົນສົ່ງ.','Contact step' => 'ຂັ້ນຕອນການຕິດຕໍ່','Billing phone' => 'ໂທລະສັບບິນ','Add billing phone field to the checkout form.' => 'ເພີ່ມຊ່ອງໃສ່ໃບບິນໂທລະສັບໃສ່ແບບຟອມຈ່າຍເງິນ.','Choose in which step to display the billing phone field.' => 'ເລືອກໃນຂັ້ນຕອນໃດເພື່ອສະແດງຊ່ອງໂທລະສັບໃບບິນ.','Show country code beside the flag' => 'ສະແດງລະຫັດປະເທດຢູ່ຂ້າງທຸງ','Show an example of a valid phone number inside phone fields' => 'ສະແດງຕົວຢ່າງຂອງເບີໂທລະສັບທີ່ຖືກຕ້ອງພາຍໃນຊ່ອງໂທລະສັບ','Do not change placeholders' => 'ຢ່າປ່ຽນຕົວຍຶດບ່ອນ','Show if not defined' => 'ສະແດງຖ້າຫາກວ່າບໍ່ໄດ້ກໍານົດ','Always show' => 'ສະ​ແດງ​ໃຫ້​ເຫັນ​ສະ​ເຫມີ​','Order notes' => 'ບັນທຶກຄໍາສັ່ງ','Define the visibility of the additional order notes field.' => 'ກໍານົດການເບິ່ງເຫັນຊ່ອງໃສ່ບັນທຶກຄໍາສັ່ງເພີ່ມເຕີມ.','Gift options' => 'ທາງເລືອກຂອງຂວັນ','Allow customers to add a gift message and other gift related options to the order.' => 'ອະນຸຍາດໃຫ້ລູກຄ້າເພີ່ມຂໍ້ຄວາມຂອງຂວັນແລະທາງເລືອກອື່ນທີ່ກ່ຽວຂ້ອງກັບຂອງຂວັນໃຫ້ກັບຄໍາສັ່ງ.','Display the gift message as part of the order details table instead of a separate section' => 'ສະແດງຂໍ້ຄວາມຂອງຂວັນເປັນສ່ວນຫນຶ່ງຂອງຕາຕະລາງລາຍລະອຽດຄໍາສັ່ງແທນທີ່ຈະເປັນພາກແຍກຕ່າງຫາກ','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ຕົວເລືອກນີ້ມີຜົນຕໍ່ໜ້າການຢືນຢັນການສັ່ງຊື້ (ໜ້າຂອບໃຈ) ແລະລາຍລະອຽດການສັ່ງຊື້ໃນໜ້າບັນຊີ, ອີເມວ ແລະໃບເກັບເງິນ.','Account matching' => 'ການຈັບຄູ່ບັນຊີ','Enable the account matching feature' => 'ເປີດໃຊ້ຄຸນສົມບັດການຈັບຄູ່ບັນຊີ','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'ເຊື່ອມໂຍງຄໍາສັ່ງຂອງລູກຄ້າຂອງແຂກກັບບັນຊີທີ່ມີຢູ່ແລ້ວຂອງພວກເຂົາເມື່ອບັນຊີທີ່ມີຢູ່ແລ້ວກັບລາຍລະອຽດການຕິດຕໍ່ຂອງລູກຄ້າ.','Display message when an account exists with the email address provided' => 'ສະແດງຂໍ້ຄວາມເມື່ອບັນຊີມີຢູ່ກັບທີ່ຢູ່ອີເມວທີ່ສະໜອງໃຫ້','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'ແທນທີ່ຊ່ອງສ້າງບັນຊີດ້ວຍການແຈ້ງເຕືອນ ແລະທາງເລືອກໃນການເຂົ້າສູ່ລະບົບ. ໃນບາງສະພາບການ, ມັນອາດຈະຖືກແນະນຳໃຫ້ປິດຕົວເລືອກນີ້ໄວ້ເພື່ອປົກປ້ອງຄວາມເປັນສ່ວນຕົວຂອງລູກຄ້າ.','Dashboard' => 'ແຜງໜ້າປັດ','Integrations' => 'ການປະສົມປະສານ','License keys' => 'ກະແຈໃບອະນຸຍາດ','Visit our website for more information about our plugins and add-ons.' => 'ຢ້ຽມຢາມເວັບໄຊທ໌ຂອງພວກເຮົາສໍາລັບຂໍ້ມູນເພີ່ມເຕີມກ່ຽວກັບ plugins ແລະ add-ons ຂອງພວກເຮົາ.','Order pay page' => 'ຄໍາສັ່ງຈ່າຍຫນ້າ','Order pay' => 'ສັ່ງຈ່າຍ','Enable order pay page optimizations' => 'ເປີດໃຊ້ການປັບແຕ່ງໜ້າຈ່າຍເງິນ','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ປ່ຽນແປງຮູບແບບຂອງຫນ້າການຈ່າຍເງິນຄໍາສັ່ງສໍາລັບຄໍາສັ່ງທີ່ມີຢູ່ແລ້ວທີ່ຍັງຄ້າງການຈ່າຍເງິນຈາກລູກຄ້າ.','Add widget areas to the order pay page' => 'ເພີ່ມພື້ນທີ່ widget ໃສ່ຫນ້າຈ່າຍເງິນຄໍາສັ່ງ','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'ພື້ນທີ່ widget ເຫຼົ່ານີ້ຖືກນໍາໃຊ້ເພື່ອເພີ່ມສັນຍາລັກຄວາມໄວ້ວາງໃຈແລະປ້າຍຄວາມໄວ້ວາງໃຈໃນຫນ້າການຈ່າຍເງິນຄໍາສັ່ງ.','Thank you page & order details layout' => 'ຂໍ​ຂອບ​ໃຈ​ຫນ້າ​ແລະ​ຮູບ​ແບບ​ລາຍ​ລະ​ອຽດ​ການ​ສັ່ງ​','Order details optimizations' => 'ການປັບແຕ່ງລາຍລະອຽດການສັ່ງຊື້','Enable thank you page and order details optimizations' => 'ເປີດໃຊ້ຫນ້າຂອບໃຈແລະຄໍາສັ່ງການເພີ່ມປະສິດທິພາບລາຍລະອຽດ','Changes the layout of order details on the thank you page and account pages.' => 'ປ່ຽນຮູບແບບຂອງລາຍລະອຽດການສັ່ງຊື້ໃນໜ້າຂອບໃຈ ແລະໜ້າບັນຊີ.','Enable order details customizations on email notifications' => 'ເປີດໃຊ້ການປັບແຕ່ງລາຍລະອຽດການສັ່ງຊື້ໃນການແຈ້ງເຕືອນອີເມວ','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ສະແດງພາກສ່ວນໃໝ່ ແລະປ່ຽນລຳດັບຂອງພາກສ່ວນໃນການແຈ້ງເຕືອນອີເມວ. ຮູບແບບຂອງລາຍລະອຽດການສັ່ງຊື້ໃນການແຈ້ງເຕືອນອີເມວຍັງຄົງບໍ່ປ່ຽນແປງ.','Thank you page' => 'ຂອບໃຈຫນ້າ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ຕົວເລືອກເຫຼົ່ານີ້ມີຜົນກະທົບກັບຫນ້າຂອບໃຈ, ເຊິ່ງເອີ້ນກັນວ່າຄໍາສັ່ງທີ່ໄດ້ຮັບຫຼືຫນ້າຢືນຢັນຄໍາສັ່ງ.','Order details layout' => 'ການຈັດວາງລາຍລະອຽດການສັ່ງຊື້','Display the order details with wide layout on the thank you page' => 'ສະແດງລາຍລະອຽດການສັ່ງຊື້ທີ່ມີຮູບແບບກວ້າງຢູ່ໃນຫນ້າຂອບໃຈ','Add widget areas to the thank you page' => 'ເພີ່ມພື້ນທີ່ widget ໃສ່ຫນ້າຂອບໃຈ','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'ພື້ນທີ່ widget ເຫຼົ່ານີ້ຖືກນໍາໃຊ້ເພື່ອເພີ່ມສັນຍາລັກຄວາມໄວ້ວາງໃຈແລະປ້າຍຄວາມໄວ້ວາງໃຈໃນຫນ້າຂອບໃຈ.','Order actions' => 'ຄຳສັ່ງສັ່ງ','Choose in which position to display the order actions.' => 'ເລືອກໃນຕຳແໜ່ງໃດເພື່ອສະແດງຄຳສັ່ງຄຳສັ່ງ.','Inside the order overview' => 'ພາຍໃນພາບລວມຂອງຄໍາສັ່ງ','After the order overview' => 'ຫຼັງຈາກສະຫຼຸບຄໍາສັ່ງ','After order sections' => 'ຫຼັງຈາກພາກສ່ວນຄໍາສັ່ງ','Order status' => 'ສະຖານະການສັ່ງຊື້','Display the order status progress bar' => 'ສະແດງແຖບສະຖານະຄໍາສັ່ງ','Choose in which position to display the section.' => 'ເລືອກໃນຕໍາແຫນ່ງໃດທີ່ຈະສະແດງພາກ.','After the order overview and payment instructions' => 'ຫຼັງຈາກລາຍລະອຽດຄໍາສັ່ງແລະຄໍາແນະນໍາການຈ່າຍເງິນ','Before the order items section' => 'ກ່ອນທີ່ຈະພາກສ່ວນລາຍການຄໍາສັ່ງ','Inside the order items section' => 'ພາຍໃນພາກສ່ວນລາຍການຄໍາສັ່ງ','After the order items section' => 'ຫຼັງຈາກພາກສ່ວນລາຍການຄໍາສັ່ງ','On the sidebar' => 'ຢູ່ແຖບດ້ານຂ້າງ','Order downloads' => 'ສັ່ງດາວໂຫລດ','Gift message' => 'ຂໍ້ຄວາມຂອງຂວັນ','Tools' => 'ເຄື່ອງມື','Troubleshooting' => 'ການແກ້ໄຂບັນຫາ','Debug options' => 'ທາງເລືອກໃນການດີບັກ','Debug mode' => 'ໂໝດດີບັກ','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'ການນໍາໃຊ້ຮູບແບບການດີບັກຜົນກະທົບຕໍ່ການປະຕິບັດເວັບໄຊທ໌. ພຽງແຕ່ໃຊ້ທາງເລືອກນີ້ໃນຂະນະທີ່ແກ້ໄຂບັນຫາ.','Load unminified assets' => 'ໂຫຼດຊັບສິນທີ່ບໍ່ຈໍາກັດ','Enhanced select fields' => 'ປັບປຸງຊ່ອງຂໍ້ມູນເລືອກ','Fix automatic zoom-in on form fields' => 'ແກ້ໄຂການຊູມເຂົ້າອັດຕະໂນມັດໃນຊ່ອງຂໍ້ມູນແບບຟອມ','Set <code>font-size</code> inside form fields to 16px' => 'ກໍານົດ <code>font-size</code> ພາຍໃນຊ່ອງແບບຟອມເປັນ 16px','Fluid Checkout' => 'ເຊັກເອົານໍ້າ','Settings' => 'ການຕັ້ງຄ່າ','Support' => 'ສະຫນັບສະຫນູນ','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">ອັບເກຣດເປັນ PRO</a> ເພື່ອປົດລັອກທາງເລືອກເພີ່ມເຕີມ.','(PRO)' => '(PRO)','(experimental)' => '(ທົດລອງ)','Please verify your phone number.' => 'ກະລຸນາຢັ້ງຢືນເບີໂທລະສັບຂອງທ່ານ.','The Bluehost Plugin' => 'ປັ໊ກອິນ Bluehost','Custom fields' => 'ຊ່ອງຂໍ້ມູນແບບກຳນົດເອງ','Enable custom shipping email field' => 'ເປີດໃຊ້ຊ່ອງອີເມລ໌ຈັດສົ່ງແບບກຳນົດເອງ','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'ເມື່ອເປີດໃຊ້ແລ້ວ, ພາກສະຫນາມອີເມລ໌ຂົນສົ່ງຈາກ plugin Bluehost ຈະຖືກເພີ່ມໃສ່ແບບຟອມເຊັກເອົາ.','Captcha Pro by BestWebSoft' => 'Captcha Pro ໂດຍ BestWebSoft','Captcha position' => 'ຕໍາແໜ່ງ Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'ກໍານົດຕໍາແຫນ່ງເພື່ອສະແດງສ່ວນ captcha. ບາງຕຳແໜ່ງອາດຈະບໍ່ເຮັດວຽກຂຶ້ນກັບປະເພດ captcha ທີ່ເລືອກ.','Selecting a pickup point is required before proceeding.' => 'ການເລືອກຈຸດຮັບແມ່ນຈໍາເປັນກ່ອນທີ່ຈະດໍາເນີນການ.','Pickup point' => 'ຈຸດຮັບ','Pickup point not selected yet.' => 'ຈຸດຮັບບໍ່ທັນເລືອກເທື່ອ.','Pickup point:' => 'ຈຸດຮັບ:','Mailchimp for WooCommerce' => 'Mailchimp ສໍາລັບ WooCommerce','Subscribe checkbox' => 'ປ່ອງໝາຍສະໝັກສະມາຊິກ','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'ຍົກເລີກຕຳແໜ່ງສຳລັບກ່ອງໝາຍສະໝັກສະມາຊິກໃນໜ້າເຊັກເອົາ ແລະສະແດງມັນຢູ່ໃນຂັ້ນຕອນການຕິດຕໍ່ສະເໝີ','Before Shipping Address' => 'ກ່ອນທີ່ຢູ່ສົ່ງ','(originally "%s")' => '(ເດີມ &quot;%s&quot;)','After Shipping Address' => 'ຫຼັງຈາກທີ່ຢູ່ຈັດສົ່ງ','Selecting a collection point is required when shipping with FermoPoint.' => 'ການເລືອກຈຸດເກັບກໍາແມ່ນຈໍາເປັນໃນເວລາທີ່ການຂົນສົ່ງກັບ FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'ຖ້າໝາຍຖືກແຈ້ງບອກການພິມຜິດໃນອີເມວໃຫ້ຜູ້ໃຊ້. (ຄຸນສົມບັດນີ້ຖືກປິດການນຳໃຊ້ເນື່ອງຈາກ Fluid Checkout ສະເໜີໃຫ້ຄຸນສົມບັດ. ການປ່ຽນແປງຕົວເລືອກນີ້ຈະບໍ່ມີຜົນກະທົບ).','Enable Mail Check: (disabled feature)' => 'ເປີດ​ໃຊ້​ງານ​ການ​ກວດ​ສອບ​ອີ​ເມລ​: (ຄຸນ​ນະ​ສົມ​ບັດ​ປິດ​ການ​ໃຊ້​ງານ​)','Carrier:' => 'ຜູ້ໃຫ້ບໍລິການ:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce Email Marketing','Sign up checkbox position' => 'ລົງທະບຽນຕໍາແຫນ່ງ checkbox','Move the sign up checkbox to the contact step' => 'ຍ້າຍກ່ອງໝາຍການລົງທະບຽນໄປຫາຂັ້ນຕອນການຕິດຕໍ່','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'ເມື່ອເປີດໃຊ້ງານ, ກ່ອງກາໝາຍຈະຖືກຍ້າຍໄປທີ່ຂັ້ນຕອນການຕິດຕໍ່ໂດຍອິສະລະຈາກສະຖານທີ່ສະແດງທີ່ກຳນົດໄວ້ໃນການຕັ້ງຄ່າ plugin Sendinblue.','Theme Betheme' => 'ຫົວຂໍ້ Betheme','Checkout progress' => 'ຄວາມຄືບໜ້າຂອງການຈ່າຍເງິນ','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຖອນເງິນຈາກ Betheme ຢູ່ໃນຫນ້າທີ່ຈ່າຍເງິນ, ກະຕ່າ ແລະຄໍາສັ່ງທີ່ໄດ້ຮັບ.','Theme Fennik' => 'ຫົວຂໍ້ Fennik','Breadcrumbs' => 'ເຂົ້າໜົມປັງ','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'ສົ່ງອອກສ່ວນ breadcrumbs ຈາກຫົວຂໍ້ Fennik ເມື່ອໃຊ້ສ່ວນຫົວແລະສ່ວນທ້າຍຂອງ Fluid Checkout.','Theme Go' => 'ຫົວຂໍ້ໄປ','My account layout' => 'ຮູບແບບບັນຊີຂອງຂ້ອຍ','Enable wide layout on "My account" page.' => 'ເປີດໃຊ້ຮູບແບບກວ້າງຢູ່ໃນຫນ້າ &quot;ບັນຊີຂອງຂ້ອຍ&quot;.','Theme Impreza' => 'ຫົວຂໍ້ Impreza','Header' => 'ສ່ວນຫົວ','Spacing for site header at the checkout page (in pixels)' => 'ໄລຍະຫ່າງສໍາລັບສ່ວນຫົວຂອງເວັບໄຊຢູ່ໜ້າຈ່າຍເງິນ (ເປັນ pixels)','Only applicable when using the Impreza theme header at the checkout page.' => 'ນຳໃຊ້ໄດ້ສະເພາະເມື່ອໃຊ້ຫົວຂໍ້ຫົວຂໍ້ Impreza ຢູ່ໜ້າຈ່າຍເງິນ.','Theme Kapee' => 'ຫົວຂໍ້ Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຈ່າຍເງິນຈາກຫົວຂໍ້ Kapee ຢູ່ໃນຫນ້າທີ່ຈ່າຍເງິນ, ກະຕ່າ ແລະຄໍາສັ່ງທີ່ໄດ້ຮັບ.','Theme Porto' => 'ຫົວຂໍ້ Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຈ່າຍເງິນຈາກຫົວຂໍ້ Porto ຢູ່ໃນຫນ້າທີ່ຈ່າຍເງິນ, ກະຕ່າ ແລະຄໍາສັ່ງທີ່ໄດ້ຮັບ.','Theme Pressmart' => 'ຫົວຂໍ້ Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຈ່າຍເງິນຈາກຫົວຂໍ້ Pressmart ຢູ່ໃນຫນ້າທີ່ຈ່າຍເງິນ, ກະຕ່າແລະຄໍາສັ່ງທີ່ໄດ້ຮັບ.','Theme The Gem' => 'ຫົວຂໍ້ແກ້ວປະເສີດ','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຈ່າຍເງິນຈາກຫົວຂໍ້ The Gem ເມື່ອໃຊ້ສ່ວນຫົວ ແລະສ່ວນທ້າຍຂອງ Fluid Checkout.','Theme Woodmart' => 'ຫົວຂໍ້ Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຈ່າຍເງິນຈາກຫົວຂໍ້ Woodmart ເມື່ອໃຊ້ສ່ວນຫົວ ແລະສ່ວນທ້າຍຂອງ Fluid Checkout.','Checkout options' => 'ທາງເລືອກການຈ່າຍເງິນ','Disable the theme checkout options' => 'ປິດການໃຊ້ງານຕົວເລືອກການຈ່າຍເງິນຮູບແບບສີສັນ','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'ທາງ​ເລືອກ​ທີ່​ສະ​ແດງ​ຮູບ​ພາບ​ຜະ​ລິດ​ຕະ​ພັນ​, ພາກ​ສະ​ຫນາມ​ປະ​ລິ​ມານ​, ເອົາ​ປຸ່ມ​ແລະ​ການ​ເຊື່ອມ​ຕໍ່​ກັບ​ຫນ້າ​ຜະ​ລິດ​ຕະ​ພັນ​ທີ່​ເພີ່ມ​ໂດຍ​ຮູບ​ແບບ​ແມ່ນ​ໄດ້​ຖືກ​ປິດ​ການ​ທໍາ​ງານ​.','Theme Atomion' => 'ຫົວຂໍ້ Atomion','Order progress' => 'ຄວາມຄືບຫນ້າຂອງຄໍາສັ່ງ','Display order progress from the theme' => 'ສະແດງຄວາມຄືບຫນ້າຄໍາສັ່ງຈາກຫົວຂໍ້','Display the form field labels visible on the page' => 'ສະແດງປ້າຍຊື່ພາກສະຫນາມແບບຟອມທີ່ເຫັນໄດ້ໃນຫນ້າ','It is recommended to keep this option enabled for a better user experience.' => 'ຂໍແນະນຳໃຫ້ເປີດຕົວເລືອກນີ້ໄວ້ເພື່ອປະສົບການຂອງຜູ້ໃຊ້ທີ່ດີຂຶ້ນ.','Theme ZK Nito' => 'ຫົວຂໍ້ ZK Nito','Add extra fields to the checkout form' => 'ເພີ່ມຊ່ອງໃສ່ຕື່ມໃສ່ແບບຟອມຈ່າຍເງິນ','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'ຕື່ມການຕື່ມຂໍ້ມູນການສົ່ງອີເມລ໌ແລະຊ່ອງໂທລະສັບຂົນສົ່ງໄປຍັງພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງ.','Go to the home page' => 'ໄປທີ່ຫນ້າທໍາອິດ','Skip to content' => 'ຂ້າມໄປຫາເນື້ອຫາ','Create an account' => 'ສ້າງບັນຊີ','Log in to your account' => 'ເຂົ້າສູ່ລະບົບບັນຊີຂອງທ່ານ','Already have an account?' => 'ມີບັນຊີຢູ່ແລ້ວບໍ?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'ເຂົ້າສູ່ລະບົບເປັນ %1$s. <a href="%2$s">ອອກຈາກລະບົບ</a>','Your order has a total amount due of %s. No further payment is needed.' => 'ການສັ່ງຊື້ຂອງເຈົ້າມີຈຳນວນທັງໝົດທີ່ຕ້ອງຈ່າຍ %s. ບໍ່ຈຳເປັນຕ້ອງຈ່າຍເງິນອີກຕໍ່ໄປ.','Close and continue with checkout' => 'ປິດ ແລະສືບຕໍ່ດ້ວຍການຈ່າຍເງິນ','Continue' => 'ສືບຕໍ່','Parcel terminal' => 'ສະຖານີ parcel','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>widget ນີ້ຖືກແທນທີ່ດ້ວຍ Fluid Checkout.</p><p> ເມື່ອໃຊ້ Fluid Checkout, ຫນ້າເຊັກເອົາຕ້ອງໃຊ້ລະຫັດສັ້ນ WooCommerce <code>[woocommerce_checkout]</code> ຕົ້ນສະບັບເພື່ອເຮັດວຽກຢ່າງຖືກຕ້ອງ.</p><p> ສໍາລັບຂໍ້ມູນເພີ່ມເຕີມ, ເຂົ້າໄປເບິ່ງເອກະສານ Fluid Checkout.</p>','Theme The7' => 'ຫົວ​ຂໍ້ 7','Additional header sections' => 'ພາກສ່ວນຫົວເພີ່ມເຕີມ','Output additional header sections if enabled in the theme settings.' => 'ສົ່ງສ່ວນຫົວເພີ່ມເຕີມຖ້າເປີດໃຊ້ໃນການຕັ້ງຄ່າຮູບແບບສີສັນ.','More information' => 'ຂໍ້ມູນເພີ່ມເຕີມ','Pick a Locker' => 'ເລືອກ Locker ເປັນ','Page template' => 'ແມ່ແບບຫນ້າ','Use `Order confirmation` page template for block-based themes' => 'ໃຊ້ແມ່ແບບຫນ້າ &#39;ການຢືນຢັນຄໍາສັ່ງ&#39; ສໍາລັບຫົວຂໍ້ທີ່ອີງໃສ່ບລັອກ','Only applies when using a block-based theme.' => 'ນຳໃຊ້ພຽງແຕ່ເມື່ອນຳໃຊ້ຮູບແບບສີສັນບຼັອກ.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'ແບບຟອມການຈ່າຍເງິນ','Apply styles to the Stripe payment form fields' => 'ນຳໃຊ້ຮູບແບບຕ່າງໆໃສ່ຊ່ອງຂໍ້ມູນແບບຟອມການຈ່າຍເງິນ Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'ເມື່ອເປີດໃຊ້ງານ, Fluid Checkout ຈະນຳໃຊ້ຄໍເຕົ້າໄຂ່ທີ່ປັບແຕ່ງໃຫ້ເຂົ້າກັນໄດ້ກັບປລັກອິນ. ທ່ານອາດຈະຕ້ອງການປິດການທໍາງານນີ້ຖ້າຫາກວ່າທ່ານກໍາລັງໃຊ້ຮູບແບບການກໍານົດເອງສໍາລັບຊ່ອງໃສ່ແບບຟອມການຈ່າຍເງິນ Stripe.','Theme Nyture' => 'ຫົວຂໍ້ Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຈ່າຍເງິນຈາກຫົວຂໍ້ Nyture ເມື່ອໃຊ້ Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'ອະນຸຍາດໃຫ້ລູກຄ້າເຮັດການຊໍາລະເງິນສໍາລັບຄໍາສັ່ງທີ່ສ້າງຂຶ້ນດ້ວຍຕົນເອງໂດຍຜູ້ເບິ່ງແຍງຮ້ານຫຼືບໍ່ໄດ້ສໍາເລັດໃນລະຫວ່າງການຈ່າຍເງິນ.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'plugin WooCommerce Checkout Manager ໂດຍ Quadlayers ບໍ່ເຂົ້າກັນໄດ້ກັບ Fluid Checkout','Company name field for billing address' => 'ຊ່ອງຂໍ້ມູນຊື່ບໍລິສັດສໍາລັບທີ່ຢູ່ໃບບິນ','Change visibility for the company name field for the billing address section on the checkout form.' => 'ປ່ຽນການເບິ່ງເຫັນຊ່ອງຂໍ້ມູນຊື່ບໍລິສັດສຳລັບພາກສ່ວນທີ່ຢູ່ໃບບິນໃນແບບຟອມຈ່າຍເງິນ.','Theme Bookshelf' => 'Theme Bookshelf','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'ສົ່ງອອກພາກສ່ວນຂັ້ນຕອນການຈ່າຍເງິນຈາກຫົວຂໍ້ Bookshelf ເມື່ອໃຊ້ Fluid Checkout.','Account password' => 'ລະຫັດຜ່ານບັນຊີ','An account will be created with the information provided at checkout when completing the order.' => 'ບັນຊີຈະຖືກສ້າງຂື້ນດ້ວຍຂໍ້ມູນທີ່ສະໜອງໃຫ້ໃນເວລາຈ່າຍເງິນໃນເວລາເຮັດການສັ່ງຊື້.','Choose the style of the progress bar.' => 'ເລືອກຮູບແບບຂອງແຖບຄວາມຄືບຫນ້າ.','Bars' => 'ບາ','Theme Ireca' => 'ຫົວຂໍ້ Ireca','WooCommerce page layout' => 'ຮູບແບບຫນ້າ WooCommerce','Force wide layout on WooCommerce pages' => 'ບັງຄັບຮູບແບບກວ້າງໃນຫນ້າ WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'ນີ້ຮັບປະກັນວ່າພາກສ່ວນເນື້ອຫາບໍ່ແຄບເກີນໄປໃນຫນ້າ WooCommerce ລວມທັງການຊໍາລະ, ໂຄງຮ່າງການ, ຄໍາສັ່ງທີ່ໄດ້ຮັບ, ຄໍາສັ່ງຈ່າຍແລະຫນ້າບັນຊີ.','WooCommerce Smart Coupons' => 'ຄູປອງອັດສະລິຍະ WooCommerce','Position on checkout page' => 'ຕຳແໜ່ງໃນໜ້າຈ່າຍເງິນ','Choose where to display the available coupons section on the checkout page.' => 'ເລືອກບ່ອນທີ່ຈະສະແດງສ່ວນຄູປອງທີ່ມີຢູ່ໃນໜ້າຈ່າຍເງິນ.','Before the progress bar' => 'ກ່ອນແຖບຄວາມຄືບຫນ້າ','After the progress bar' => 'ຫຼັງຈາກແຖບຄວາມຄືບຫນ້າ','Before coupon codes section' => 'ກ່ອນທີ່ຈະພາກສ່ວນລະຫັດຄູປອງ','Format phone numbers according to the rules for each country.' => 'ຮູບແບບເບີໂທລະສັບຕາມກົດລະບຽບຂອງແຕ່ລະປະເທດ.','Use precise phone number validation' => 'ໃຊ້ການກວດສອບເບີໂທລະສັບທີ່ຊັດເຈນ','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'ນີ້ແມ່ນຄຸນສົມບັດທົດລອງ ແລະອາດຈະບໍ່ເຮັດວຽກຕາມທີ່ຄາດໄວ້ໃນທຸກການຕັ້ງຄ່າ. ໃຊ້ມັນດ້ວຍຄວາມລະມັດລະວັງ.','Phone number validation types used when precise validation is enabled.' => 'ປະເພດການກວດສອບເບີໂທລະສັບທີ່ໃຊ້ໃນເວລາທີ່ການກວດສອບຄວາມຖືກຕ້ອງຖືກເປີດໃຊ້.','Mobile' => 'ມືຖື','Fixed line' => 'ສາຍຄົງທີ່','Toll free' => 'ໂທຟຣີ','Or' => 'ຫຼື','Contact' => 'ຕິດຕໍ່','Multi step' => 'ຫຼາຍຂັ້ນຕອນ','2 columns' => '2 ຖັນ','1 column' => '1 ຖັນ','Before checkout steps' => 'ຂັ້ນຕອນກ່ອນການຈ່າຍເງິນ','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'ເມື່ອໃຊ້ຮູບແບບການຈ່າຍເງິນ <em>&quot;1 ຖັນ&quot;</em> ຕົວເລືອກນີ້ຈະຖືກຕັ້ງເປັນ <em>&quot;ກ່ອນຂັ້ນຕອນການຈ່າຍເງິນ&quot;</em> ສະເໝີ ແລະ ຍັງໃຊ້ກັບມຸມມອງເດັສທັອບນຳອີກ.','Position for the extra order summary section on mobile.' => 'ຕຳແໜ່ງສຳລັບພາກສ່ວນສະຫຼຸບການສັ່ງຊື້ເພີ່ມເຕີມໃນມືຖື.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'ຕົວເລືອກ <em>&quot;ຫົວຂໍ້ໃນເວັບໄຊທ໌&quot;</em> ໃຊ້ໄດ້ສະເພາະເມື່ອໃຊ້ຫົວຂໍ້ທີ່ບໍ່ມີສິ່ງລົບກວນເທົ່ານັ້ນ.','On the site header (requires distraction-free header)' => 'ໃນຫົວຂໍ້ຂອງເວັບໄຊທ໌ (ຕ້ອງການຫົວຂໍ້ທີ່ບໍ່ມີສິ່ງລົບກວນ)','Initial state for the expansible order summary section on mobile.' => 'ສະຖານະເບື້ອງຕົ້ນສຳລັບພາກສ່ວນສະຫຼຸບຄຳສັ່ງຊື້ທີ່ສາມາດຂະຫຍາຍໄດ້ໃນມືຖື.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'ພວກເຮົາແນະນຳໃຫ້ຕັ້ງມັນເປັນ <em>ຂະຫຍາຍ</em> ສຳລັບປະເທດຕໍ່ໄປນີ້ເນື່ອງຈາກຂໍ້ກຳນົດດ້ານກົດລະບຽບ: <strong>ເຢຍລະມັນ</strong> , <strong>ອອສເຕຣຍ</strong> , <strong>ສະວິດ</strong> ເຊີແລນ, <strong>ເນເທີແລນ</strong> , <strong>ໂປແລນ</strong> , <strong>ແບນຊິກ</strong> ແລະ <strong>ຝຣັ່ງ</strong> .','Collapsed' => 'ຫຍໍ້ລົງ','Expanded' => 'ຂະຫຍາຍແລ້ວ','Do not show' => 'ຢ່າສະແດງ','yes' => 'ແມ່ນແລ້ວ','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ຊ່ອງເບີໂທລະສັບສຳລັບສົ່ງສິນຄ້າອາດຈະຖືກບັງຄັບໃຫ້ເປັນ &quot;ຕ້ອງໃສ່&quot; ຖ້າພາກສ່ວນທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນຖືກສະແດງຫຼັງຈາກພາກສ່ວນທີ່ຢູ່ສຳລັບການຈັດສົ່ງ, ແລະຊ່ອງເບີໂທລະສັບສຳລັບສົ່ງສິນຄ້າຖືກຕັ້ງເປັນ &quot;ຕ້ອງໃສ່&quot;. ນີ້ແມ່ນຈຳເປັນເພື່ອຮັບປະກັນວ່າທີ່ຢູ່ສຳລັບການຈັດສົ່ງສາມາດຖືກຄັດລອກໄປຫາທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນໄດ້ເມື່ອເລືອກຕົວເລືອກນັ້ນ, ຖ້າບໍ່ດັ່ງນັ້ນລູກຄ້າອາດຈະບໍ່ສາມາດຕື່ມແບບຟອມຊຳລະເງິນໄດ້.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ຊ່ອງເບີໂທລະສັບສຳລັບການຮຽກເກັບເງິນອາດຈະຖືກບັງຄັບໃຫ້ເປັນ &quot;ຕ້ອງໃສ່&quot; ຖ້າພາກສ່ວນທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນຖືກສະແດງກ່ອນພາກສ່ວນທີ່ຢູ່ຈັດສົ່ງ, ແລະຊ່ອງເບີໂທລະສັບສຳລັບການຈັດສົ່ງຖືກຕັ້ງເປັນ &quot;ຕ້ອງໃສ່&quot;. ນີ້ແມ່ນຈຳເປັນເພື່ອຮັບປະກັນວ່າທີ່ຢູ່ຈັດສົ່ງສາມາດຖືກຄັດລອກໄປຫາທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນໄດ້ເມື່ອເລືອກຕົວເລືອກນັ້ນ, ຖ້າບໍ່ດັ່ງນັ້ນລູກຄ້າອາດຈະບໍ່ສາມາດຕື່ມແບບຟອມຊຳລະເງິນໄດ້.','Settings profiles' => 'ໂປຣໄຟລ໌ການຕັ້ງຄ່າ','Settings profile' => 'ໂປຣໄຟລ໌ການຕັ້ງຄ່າ','You do not have permission to perform this action.' => 'ທ່ານບໍ່ມີສິດໃນການປະຕິບັດການກະທຳນີ້.','You do not have permission to activate plugins.' => 'ທ່ານບໍ່ມີສິດໃນການເປີດໃຊ້ງານປລັກອິນ.','Missing plugin.' => 'ບໍ່ມີປລັກອິນ.','Plugin activated.' => 'ປລັກອິນເປີດໃຊ້ງານແລ້ວ.','The following changes will be applied:' => 'ການປ່ຽນແປງຕໍ່ໄປນີ້ຈະຖືກນຳໃຊ້:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'ນັບຕັ້ງແຕ່ Fluid Checkout 5.0, ການຕັ້ງຄ່າຈະຖືກບັນທຶກໄວ້ແຕກຕ່າງກັນ. ຕົວເລືອກ Legacy ຍັງຖືກເກັບໄວ້ໃນຖານຂໍ້ມູນເພື່ອອະນຸຍາດໃຫ້ຫຼຸດລະດັບເປັນເວີຊັນກ່ອນໜ້ານີ້ໄດ້ຖ້າຈຳເປັນ.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'ຮ້ານຄ້າຂອງທ່ານໄດ້ເປີດໃຊ້ງານການຕັ້ງຄ່າໃໝ່ມາປະມານ 2 ອາທິດແລ້ວ ດັ່ງນັ້ນທ່ານສາມາດລຶບຕົວເລືອກເກົ່າທີ່ເກັບໄວ້ໃນຖານຂໍ້ມູນໄດ້. ກະລຸນາຮັບຊາບວ່າຫຼັງຈາກການລຶບລ້າງແລ້ວ, ຖ້າທ່ານຕ້ອງການຫຼຸດລະດັບປລັກອິນໄປໃຊ້ເວີຊັນກ່ອນໜ້ານີ້ ມັນຈະໃຊ້ຄ່າເລີ່ມຕົ້ນສຳລັບການຕັ້ງຄ່າທັງໝົດ.','Fluid Checkout settings cleanup' => 'ການເຮັດຄວາມສະອາດການຕັ້ງຄ່າ Fluid Checkout','Delete leftover options' => 'ລຶບຕົວເລືອກທີ່ເຫຼືອ','Help us improve Fluid Checkout' => 'ຊ່ວຍພວກເຮົາປັບປຸງການຈ່າຍເງິນຜ່ານນໍ້າ','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'ແບ່ງປັນລາຍງານສະພາບແວດລ້ອມເວັບໄຊທ໌ທີ່ບໍ່ລະບຸຊື່ກັບ Fluid Checkout ເພື່ອຮັບການສະໜັບສະໜູນໄວຂຶ້ນ ແລະ ຊ່ວຍພວກເຮົາປັບປຸງຄວາມເຂົ້າກັນໄດ້ ແລະ ວັດແທກຜົນກະທົບ. ບໍ່ມີລູກຄ້າ, ຜູ້ໃຊ້ ຫຼື ຂໍ້ມູນທີ່ລະອຽດອ່ອນລວມຢູ່ນຳ. ທ່ານສາມາດເລືອກສິ່ງທີ່ຈະແບ່ງປັນໄດ້ທຸກເວລາຈາກການຕັ້ງຄ່າເຄື່ອງມື.','Enable site environment reports' => 'ເປີດໃຊ້ລາຍງານສະພາບແວດລ້ອມຂອງເວັບໄຊ','Review settings' => 'ກວດສອບການຕັ້ງຄ່າ','This preview has expired. Reload the admin page to start a new preview.' => 'ຕົວຢ່າງນີ້ໝົດອາຍຸແລ້ວ. ໂຫຼດໜ້າຜູ້ເບິ່ງແຍງລະບົບຄືນໃໝ່ເພື່ອເລີ່ມຕົ້ນຕົວຢ່າງໃໝ່.','Preview expired' => 'ຕົວຢ່າງໝົດອາຍຸແລ້ວ','Orders cannot be placed in the preview.' => 'ບໍ່ສາມາດວາງຄຳສັ່ງຊື້ໃນການສະແດງຕົວຢ່າງໄດ້.','Logging in is not available in the preview.' => 'ການເຂົ້າສູ່ລະບົບບໍ່ສາມາດໃຊ້ໄດ້ໃນການສະແດງຕົວຢ່າງ.','Accounts cannot be created in the preview.' => 'ບໍ່ສາມາດສ້າງບັນຊີໃນການສະແດງຕົວຢ່າງໄດ້.','Requests to other sites are blocked in the preview.' => 'ການຮ້ອງຂໍໄປຫາເວັບໄຊທ໌ອື່ນຖືກບລັອກໃນການສະແດງຕົວຢ່າງ.','Processing…' => 'ກຳລັງປະມວນຜົນ…','Something went wrong. Please try again.' => 'ມີບາງຢ່າງຜິດພາດເກີດຂຶ້ນ. ກະລຸນາລອງໃໝ່ອີກຄັ້ງ.','Activate plugin' => 'ເປີດໃຊ້ປລັກອິນ','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - ຊຸດຊຳລະເງິນທີ່ສົມບູນ','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'ຄຸນສົມບັດ PRO ທັງໝົດ + ສ່ວນເສີມທັງໝົດ, ລາຄາດຽວ. ອອກແບບແມ່ແບບ, ໜ້າກະຕ່າສິນຄ້າ ແລະ ໜ້າທີ່ໄດ້ຮັບຄຳສັ່ງຊື້ທີ່ດີທີ່ສຸດ, ການຈັບຄູ່ບັນຊີ, ແລະ ອື່ນໆອີກຫຼາຍຢ່າງ.','Optimized order pay page' => 'ໜ້າຈ່າຍເງິນສັ່ງຊື້ທີ່ດີທີ່ສຸດ','Express checkout buttons from supported payment methods' => 'ປຸ່ມຈ່າຍເງິນດ່ວນຈາກວິທີການຈ່າຍເງິນທີ່ຮອງຮັບ','Delayed account creation' => 'ການສ້າງບັນຊີຊັກຊ້າ','Address autocomplete with Google Maps APIs' => 'ການຕື່ມຂໍ້ມູນທີ່ຢູ່ໂດຍອັດຕະໂນມັດດ້ວຍ Google Maps APIs','Multiple saved addresses with the address book' => 'ທີ່ຢູ່ຫຼາຍອັນທີ່ບັນທຶກໄວ້ພ້ອມກັບປຶ້ມທີ່ຢູ່','EU-VAT assistant' => 'ຜູ້ຊ່ວຍ EU-VAT','Hide this section' => 'ເຊື່ອງພາກສ່ວນນີ້','Learn more' => 'ຮຽນຮູ້ເພີ່ມເຕີມ','Get early access' => 'ຮັບສິດເຂົ້າໃຊ້ກ່ອນໄວອັນຄວນ','Activate add-on' => 'ເປີດໃຊ້ແອດອອນ','Get more out of your checkout journey' => 'ໄດ້ຮັບປະໂຫຍດຫຼາຍຂຶ້ນຈາກການເດີນທາງການຈ່າຍເງິນຂອງທ່ານ','Test API key' => 'ລະຫັດ API ທົດສອບ','Guided setup' => 'ການຕັ້ງຄ່າແບບມີຄູ່ມື','Options' => 'ຕົວເລືອກຕ່າງໆ','Set up layout and design on the <a href="%s">checkout options</a>.' => 'ຕັ້ງຄ່າຮູບແບບ ແລະ ການອອກແບບໃນ <a href="%s">ຕົວເລືອກການຈ່າຍເງິນ</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'ເປີດໃຊ້ການຈ່າຍເງິນແບບແຂກ ແລະ/ຫຼື ກວດສອບ <a href="%s">ການຕັ້ງຄ່າບັນຊີລູກຄ້າ</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'ເປີດໃຊ້ <a href="%1$s">ໜ້າກະຕ່າສິນຄ້າ</a> ທີ່ໄດ້ຮັບການປັບປຸງໃຫ້ດີທີ່ສຸດ, <a href="%2$s">ໜ້າຂອບໃຈ</a> ແລະ ໜ້າ <a href="%3$s">ຈ່າຍເງິນສຳລັບການສັ່ງຊື້</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'ເປີດໃຊ້ <a href="%s">ການຕື່ມຂໍ້ມູນທີ່ຢູ່ອັດຕະໂນມັດ</a> ຈາກ Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'ເປີດໃຊ້ທີ່ຢູ່ທີ່ບັນທຶກໄວ້ຫຼາຍອັນດ້ວຍ <a href="%s">ປຶ້ມທີ່ຢູ່</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'ກວດສອບວ່າມີ <a href="%s">ຕົວເລືອກການເຊື່ອມໂຍງ</a> ໃດໆທີ່ມີໃຫ້ສຳລັບຮູບແບບ ຫຼື ປລັກອິນອື່ນໆທີ່ທ່ານໄດ້ຕິດຕັ້ງໄວ້.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'ຮັບການຊ່ວຍເຫຼືອໄວຂຶ້ນ ແລະ ຊ່ວຍພວກເຮົາປັບປຸງຄວາມເຂົ້າກັນໄດ້ ແລະ ວັດແທກຜົນກະທົບ. <a href="%s">ເປີດໃຊ້ການຕິດຕາມການນຳໃຊ້</a> ຈາກການຕັ້ງຄ່າເຄື່ອງມື.','Missing settings tab.' => 'ແຖບການຕັ້ງຄ່າຫາຍໄປ.','Getting started' => 'ການເລີ່ມຕົ້ນ','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>ດີຫຼາຍ! ໜ້າຈ່າຍເງິນຂອງທ່ານກຳລັງເຮັດວຽກຢູ່ໃນ Fluid Checkout.</strong> ນີ້ແມ່ນຂັ້ນຕອນບາງຢ່າງເພື່ອເລີ່ມຕົ້ນ:','Completed' => 'ສຳເລັດແລ້ວ','Preview report data' => 'ສະແດງຕົວຢ່າງຂໍ້ມູນລາຍງານ','Send now' => 'ສົ່ງດຽວນີ້','Auto-detect' => 'ກວດຫາອັດຕະໂນມັດ','Afrikaans' => 'ອາຟຣິກັນ','Albanian' => 'ອານບານີ','Amharic' => 'ອຳຮາຣິກ','Arabic' => 'ພາສາອາຣັບ','Armenian' => 'ອາເມເນຍ','Azerbaijani' => 'ອາເຊີໄບຈັນ','Basque' => 'ບາສເກສ','Belarusian' => 'ເບລາຣຸສ','Bengali' => 'ເບັງກາລີ','Bosnian' => 'ບອສເນຍ','Bulgarian' => 'ບຸນກາຣີ','Burmese' => 'ພາສາພະມ້າ','Catalan' => 'ກາຕາລັງ','Chinese' => 'ພາສາຈີນ','Chinese (Simplified)' => 'ພາສາຈີນ (ງ່າຍ)','Chinese (Hong Kong)' => 'ຈີນ (ຮ່ອງກົງ)','Chinese (Traditional)' => 'ພາສາຈີນ (ແບບດັ້ງເດີມ)','Croatian' => 'ພາສາໂຄຣເອເຊຍ','Czech' => 'ເຊັກ','Danish' => 'ພາສາເດນມາກ','Dutch' => 'ໂຮນລັງ','English' => 'ພາສາອັງກິດ','English (Australian)' => 'ອັງກິດ (ອົດສະຕຣາລີ)','English (Great Britain)' => 'ພາສາອັງກິດ (ສະຫະລາຊະອານາຈັກ)','Estonian' => 'ເອສໂຕເນຍ','Farsi' => 'ຟາຊີ','Finnish' => 'ພາສາຟິນແລນ','Filipino' => 'ພາສາຟິລິບປິນ','French' => 'ພາສາຝຣັ່ງ','French (Canadian)' => 'ຝຣັ່ງ (ການາດາ)','Galician' => 'ກາລິຊຽນ','Georgian' => 'ຈໍເຈຍ','German' => 'ເຢຍລະມັນ','Greek' => 'ພາສາກຣີກ','Gujarati' => 'ກູຣາຈາຣາຕີ','Hebrew' => 'ພາສາເຮັບເຣີ','Hindi' => 'ຮິນດີ','Hungarian' => 'ຮັງກາຣີ','Icelandic' => 'ໄອສແລນ','Indonesian' => 'ອິນໂດເນເຊຍ','Italian' => 'ອິຕາລີ','Japanese' => 'ພາສາຍີ່ປຸ່ນ','Kannada' => 'ກັນນາດາ','Kazakh' => 'ຄາຊັກ','Khmer' => 'ຂະເໝນ','Korean' => 'ພາສາເກົາຫຼີ','Kyrgyz' => 'ຄີກກີຊ','Lao' => 'ລາວ','Latvian' => 'ລັດເວຍ','Lithuanian' => 'ລິທົວເນຍ','Macedonian' => 'ມາເຊໂດເນຍ','Malay' => 'ມາເລ','Malayalam' => 'ມາລາຢາລຳ','Marathi' => 'ມາຣາທີ','Mongolian' => 'ມົງໂກນ','Nepali' => 'ເນປານ','Norwegian' => 'ພາສານໍເວ','Polish' => 'ພາສາໂປໂລຍ','Portuguese' => 'ປອກຕຸຍການ','Portuguese (Brazil)' => 'ປອກຕຸຍການ (ບຣາຊິວ)','Portuguese (Portugal)' => 'ປອກຕຸຍການ (ປອກຕຸຍການ)','Punjabi' => 'ພາສາປັນຈາບີ','Romanian' => 'ພາສາໂຣມາເນຍ','Russian' => 'ພາສາລັດເຊຍ','Serbian' => 'ເຊີເບຍ','Sinhalese' => 'ສິຫລາ','Slovak' => 'ສະໂລວາເກຍ','Slovenian' => 'ສະໂລເວເນຍ','Spanish' => 'ພາສາສະເປນ','Spanish (Latin America)' => 'ສະເປນ (ລາຕິນອາເມລິກາ)','Swahili' => 'ພາສາຊວາຮີລີ','Swedish' => 'ຊູແອັດ','Tamil' => 'ທະມິນ','Telugu' => 'ພາສາເຕລູກູ','Thai' => 'ໄທ','Turkish' => 'ພາສາຕຸລະກີ','Ukrainian' => 'ພາສາຢູເຄຣນ','Urdu' => 'ອູຣດູ','Vietnamese' => 'ຫວຽດນາມ','Zulu' => 'ຊູລູ','Google address autocomplete' => 'ການຕື່ມຂໍ້ມູນທີ່ຢູ່ Google ໂດຍອັດຕະໂນມັດ','Google Places API version' => 'ເວີຊັນ API ຂອງ Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'ເລືອກວ່າຈະໃຊ້ Google Places API ເວີຊັນໃດ. ພວກເຮົາແນະນຳໃຫ້ຍ້າຍໄປໃຊ້ Places API ໃໝ່ໄວເທົ່າທີ່ຈະໄວໄດ້.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'ພວກເຮົາແນະນຳໃຫ້ໃຊ້ &quot;Places API (ໃໝ່)&quot; ເນື່ອງຈາກມີຜົນບັງຄັບໃຊ້ໃນວັນທີ 1 ມີນາ 2025, Google ຈະຍ້າຍເວີຊັນ &quot;Places API (ເກົ່າ)&quot; ໄປສູ່ສະຖານະເກົ່າ, ຊຶ່ງໝາຍຄວາມວ່າທ່ານຈະບໍ່ສາມາດເປີດໃຊ້ບໍລິການນີ້ສຳລັບລະຫັດ API ໃໝ່ໄດ້ອີກຕໍ່ໄປ ແລະ API ເວີຊັນນັ້ນໃນທີ່ສຸດຈະບໍ່ສາມາດໃຊ້ໄດ້ອີກຕໍ່ໄປ. ບັນຊີທີ່ມີຢູ່ແລ້ວທີ່ໃຊ້ Legacy API ແລ້ວອາດຈະສືບຕໍ່ເຮັດວຽກໂດຍບໍ່ມີການຂັດຂວາງ.','(Recommended)' => '(ແນະນຳ)','Google API key' => 'ລະຫັດ Google API','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'ວາງລະຫັດ Google API ຂອງທ່ານ ແລະ ໃຊ້ປຸ່ມທົດສອບເພື່ອຢືນຢັນວ່າມັນໃຊ້ໄດ້ກັບເວັບໄຊທ໌ນີ້. ໃຫ້ແນ່ໃຈວ່າລະຫັດຖືກຕ້ອງ ແລະ ໄດ້ຮັບອະນຸຍາດສຳລັບໂດເມນຂອງທ່ານ, ຖ້າບໍ່ດັ່ງນັ້ນຊ່ອງທີ່ຢູ່ອາດຈະຖືກບລັອກ ເຊິ່ງເຮັດໃຫ້ລູກຄ້າບໍ່ສາມາດເຮັດສຳເລັດຄຳສັ່ງຊື້ຂອງເຂົາເຈົ້າໄດ້.','Enable Google address autocomplete' => 'ເປີດໃຊ້ການຕື່ມຂໍ້ມູນທີ່ຢູ່ Google ໂດຍອັດຕະໂນມັດ','Enable address autocompletion using the Google Maps APIs.' => 'ເປີດໃຊ້ການຕື່ມຂໍ້ມູນທີ່ຢູ່ໂດຍອັດຕະໂນມັດໂດຍໃຊ້ Google Maps APIs.','Google API language' => 'ພາສາ Google API','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'ພາສານີ້ຈະຖືກນໍາໃຊ້ເພື່ອສະແດງຄໍາແນະນໍາທີ່ຢູ່ Google Places API ແລະທີ່ຢູ່ຕ່າງໆກໍ່ຈະຖືກຕື່ມຂໍ້ມູນອັດຕະໂນມັດໃນພາສານີ້.','Result types' => 'ປະເພດຜົນໄດ້ຮັບ','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ປ່ອຍໃຫ້ວ່າງເພື່ອຍອມຮັບຜົນໄດ້ຮັບປະເພດໃດກໍ່ຕາມ, ເຊິ່ງໂດຍປົກກະຕິແລ້ວຈະໃຫ້ຜົນໄດ້ຮັບທີ່ກົງກັນດີກວ່າ. <a href="%s" target="_blank">ເບິ່ງເອກະສານສຳລັບລາຍລະອຽດເພີ່ມເຕີມ</a> .<br> ເລືອກຜົນການຄົ້ນຫາທີ່ຢູ່ສູງສຸດ 5 ປະເພດເພື່ອສົ່ງຄືນໃນຊ່ອງຕື່ມຂໍ້ມູນອັດຕະໂນມັດຂອງທີ່ຢູ່.<br> ເຂົ້າເບິ່ງເອກະສານ Google Maps ເພື່ອຮຽນຮູ້ເພີ່ມເຕີມກ່ຽວກັບ <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ປະເພດທີ່ຮອງຮັບ</a> .','Result types (Legacy API)' => 'ປະເພດຜົນໄດ້ຮັບ (API ລຸ້ນເກົ່າ)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'ຜົນການຄົ້ນຫາທີ່ຢູ່ປະເພດໃດທີ່ຈະສົ່ງຄືນເມື່ອໃຊ້ Places API (Legacy).<br> ເຂົ້າເບິ່ງເອກະສານຂອງ Legacy Google Places API ເພື່ອຮຽນຮູ້ເພີ່ມເຕີມກ່ຽວກັບ <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">ປະເພດທີ່ຮອງຮັບ</a> .','Company fields' => 'ສາຂາບໍລິສັດ','Enable autocomplete for the company name if available' => 'ເປີດໃຊ້ການຕື່ມຂໍ້ມູນອັດຕະໂນມັດສຳລັບຊື່ບໍລິສັດ ຖ້າມີ','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'ເປີດໃຊ້ການຕື່ມຂໍ້ມູນອັດຕະໂນມັດຂອງຊ່ອງຂໍ້ມູນບໍລິສັດດ້ວຍຂໍ້ມູນຊື່ບໍລິສັດເມື່ອສົ່ງຄືນຈາກ Google Maps APIs.','Business search' => 'ຄົ້ນຫາທຸລະກິດ','Enable search for businesses in the company field' => 'ເປີດໃຊ້ການຄົ້ນຫາທຸລະກິດໃນຊ່ອງຂໍ້ມູນບໍລິສັດ','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'ເປີດໃຊ້ການແນະນຳທີ່ຢູ່ທີ່ກ່ຽວຂ້ອງກັບທຸລະກິດເມື່ອພິມໃສ່ຊ່ອງຂໍ້ມູນບໍລິສັດ, ຈາກນັ້ນຕື່ມຂໍ້ມູນໃສ່ຊ່ອງຂໍ້ມູນທີ່ຢູ່ທັງໝົດໂດຍອັດຕະໂນມັດເມື່ອເລືອກທຸລະກິດຈາກການແນະນຳ.','Company result types' => 'ປະເພດຜົນໄດ້ຮັບຂອງບໍລິສັດ','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ເລືອກຜົນການຄົ້ນຫາທີ່ຢູ່ສູງສຸດ 5 ປະເພດເພື່ອສົ່ງຄືນໃນຊ່ອງຂໍ້ມູນບໍລິສັດທີ່ຕື່ມຂໍ້ມູນອັດຕະໂນມັດ.<br> ຄ່າທີ່ແນະນຳແມ່ນ <code>establishment</code> , ເຊິ່ງລວມມີທຸລະກິດສ່ວນໃຫຍ່.<br> ປ່ອຍໃຫ້ວ່າງເພື່ອຍອມຮັບຜົນໄດ້ຮັບປະເພດໃດກໍ່ຕາມ, ລວມທັງຜົນໄດ້ຮັບທີ່ບໍ່ກ່ຽວຂ້ອງກັບທຸລະກິດຕ່າງໆ.<br> ເຂົ້າເບິ່ງເອກະສານ Google Maps ເພື່ອຮຽນຮູ້ເພີ່ມເຕີມກ່ຽວກັບ <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ປະເພດທີ່ຮອງຮັບ</a> .','Google logo' => 'ໂລໂກ້ Google','Show text and logo "Powered by Google"' => 'ສະແດງຂໍ້ຄວາມ ແລະ ໂລໂກ້ &quot;ຂັບເຄື່ອນໂດຍ Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'ເມື່ອເລືອກແລ້ວ, ຂໍ້ຄວາມ ແລະ ໂລໂກ້ &quot;ຂັບເຄື່ອນໂດຍ Google&quot; ຈະສະແດງຢູ່ທາງລຸ່ມຂອງກ່ອງຄຳແນະນຳການຕື່ມຂໍ້ມູນທີ່ຢູ່ໂດຍອັດຕະໂນມັດ.','Brasil API address autocomplete' => 'ການຕື່ມຂໍ້ມູນອັດຕະໂນມັດທີ່ຢູ່ API ຂອງບຣາຊິນ','Brasil API' => 'API ຂອງບຣາຊິນ','Enable Brasil API address autocomplete for CEP fields' => 'ເປີດໃຊ້ການຕື່ມຂໍ້ມູນອັດຕະໂນມັດທີ່ຢູ່ Brasil API ສຳລັບຊ່ອງຂໍ້ມູນ CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'ໃຊ້ Brasil API ເພື່ອດຶງຂໍ້ມູນ ແລະ ຕື່ມຂໍ້ມູນໃສ່ທີ່ຢູ່ໂດຍອັດຕະໂນມັດໂດຍໃຊ້ຊ່ອງຂໍ້ມູນ CEP/ລະຫັດໄປສະນີ. ກ່ຽວຂ້ອງກັບທີ່ຢູ່ຂອງປະເທດບຣາຊິນເທົ່ານັ້ນ.','API version' => 'ເວີຊັນ API','Choose which version of the Brasil API CEP method to use.' => 'ເລືອກວ່າຈະໃຊ້ວິທີການ Brasil API CEP ເວີຊັນໃດ.','Address book migration' => 'ການຍ້າຍຂໍ້ມູນປື້ມທີ່ຢູ່','WooCommerce addresses' => 'ທີ່ຢູ່ WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'ຄັດລອກທີ່ຢູ່ຈັດສົ່ງ ແລະ ທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນທີ່ມີຢູ່ແລ້ວຈາກ WooCommerce ໄປໃສ່ໃນປຶ້ມທີ່ຢູ່ຂອງລູກຄ້າ.','Enable the address book feature' => 'ເປີດໃຊ້ຄຸນສົມບັດປຶ້ມທີ່ຢູ່','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ອະນຸຍາດໃຫ້ລູກຄ້າບັນທຶກທີ່ຢູ່ຫຼາຍອັນ ແລະ ກຳນົດທີ່ຢູ່ເລີ່ມຕົ້ນທີ່ຈະໃຊ້ສຳລັບການຂົນສົ່ງ ແລະ ການຮຽກເກັບເງິນ.','Address labels' => 'ປ້າຍຊື່ທີ່ຢູ່','Allow customers to add a custom label for each address' => 'ອະນຸຍາດໃຫ້ລູກຄ້າເພີ່ມປ້າຍກຳກັບແບບກຳນົດເອງສຳລັບແຕ່ລະທີ່ຢູ່','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'ປ້າຍທີ່ຢູ່ເຮັດໃຫ້ລູກຄ້າສາມາດຈຳແນກທີ່ຢູ່ທີ່ບັນທຶກໄວ້ໄດ້ງ່າຍຂຶ້ນ (ຕົວຢ່າງ: &quot;ເຮືອນຂອງແມ່&quot;). ປ້າຍທີ່ຢູ່ແມ່ນເປັນສ່ວນຕົວຂອງລູກຄ້າ, ແລະຈະບໍ່ຖືກສະແດງ ຫຼື ພິມຢູ່ໃນໜ້າລາຍລະອຽດການສັ່ງຊື້ ຫຼື ໃບແຈ້ງໜີ້.','Display layout' => 'ຮູບແບບການສະແດງຜົນ','Choose how saved addresses are displayed at checkout and on the cart.' => 'ເລືອກວິທີການສະແດງທີ່ຢູ່ທີ່ບັນທຶກໄວ້ໃນເວລາຊຳລະເງິນ ແລະ ຢູ່ໃນກະຕ່າ.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ໃຊ້ໄດ້ໃນເວລາຊຳລະເງິນ ແລະ ໃນກະຕ່າສິນຄ້າ. ທີ່ຢູ່ທີ່ບັນທຶກໄວ້ໃນໜ້າບັນຊີຈະໃຊ້ຮູບແບບບັດສະເໝີ.','Address cards' => 'ບັດທີ່ຢູ່','Address list' => 'ລາຍຊື່ທີ່ຢູ່','Dropdown field' => 'ຊ່ອງຂໍ້ມູນແບບເລື່ອນລົງ','Address search' => 'ຄົ້ນຫາທີ່ຢູ່','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'ສະແດງຕົວກອງການຄົ້ນຫາທີ່ຢູ່ຢູ່ໜ້າເວັບເມື່ອລູກຄ້າມີທີ່ຢູ່ທີ່ບັນທຶກໄວ້ຢ່າງໜ້ອຍຈຳນວນນີ້.','Not used when display layout is set to dropdown field.' => 'ບໍ່ໃຊ້ເມື່ອຮູບແບບການສະແດງຜົນຖືກຕັ້ງໃຫ້ເປັນຊ່ອງຂໍ້ມູນແບບເລື່ອນລົງ.','Addresses' => 'ທີ່ຢູ່','Enable cart page optimizations to see more options' => 'ເປີດໃຊ້ການເພີ່ມປະສິດທິພາບໜ້າກະຕ່າເພື່ອເບິ່ງຕົວເລືອກເພີ່ມເຕີມ','Sticky order summary' => 'ສະຫຼຸບຄຳສັ່ງຊື້ທີ່ໜຽວແໜ້ນ','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ເລືອກຕຳແໜ່ງທີ່ຈະສະແດງພາກສ່ວນລະຫັດຄູປອງໃນໜ້າກະຕ່າສິນຄ້າ. ໃຊ້ໄດ້ສະເພາະເມື່ອເປີດໃຊ້ກະຕ່າສິນຄ້າ AJAX ເທົ່ານັ້ນ, ແລະ ຖ້າເປີດໃຊ້ການໃຊ້ລະຫັດຄູປອງໃນການຕັ້ງຄ່າ WooCommerce.','Layout of cross-sell' => 'ຮູບແບບການຂາຍຂ້າມ','Cross-sells displayed' => 'ສະແດງການຂາຍຂ້າມ','Items' => 'ລາຍການ','Cart page optimization' => 'ການເພີ່ມປະສິດທິພາບໜ້າກະຕ່າສິນຄ້າ','Give your cart the same clear, conversion-focused layout as your checkout.' => 'ໃຫ້ຮູບແບບທີ່ຊັດເຈນ ແລະ ເນັ້ນໃສ່ການປ່ຽນໃຈເຫລື້ອມໃສຄືກັນກັບການຈ່າຍເງິນຂອງທ່ານ.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'ຈັບຄູ່ຮູບແບບກະຕ່າສິນຄ້າກັບໜ້າຈ່າຍເງິນເພື່ອໃຫ້ການຊື້ມີຄວາມສອດຄ່ອງ.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'ຮັກສາກະຕ່າສິນຄ້າໃຫ້ອັບເດດຢູ່ສະເໝີໃນພື້ນຫຼັງ, ບໍ່ມີການໂຫຼດໜ້າເວັບເຕັມເມື່ອປະລິມານມີການປ່ຽນແປງ.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'ວາງລະຫັດຄູປອງ, ຄ່າຂົນສົ່ງ ແລະ ການຂາຍຂ້າມບ່ອນທີ່ພວກມັນປ່ຽນໃຈເຫລື້ອມໃສໄດ້ດີທີ່ສຸດ.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'ຮັກສາສະຫຼຸບການສັ່ງຊື້ໃຫ້ເຫັນໄດ້ໃນຂະນະທີ່ເລື່ອນລົງ, ແລະ ເພີ່ມສັນຍາລັກຄວາມໄວ້ວາງໃຈບ່ອນທີ່ຜູ້ຊື້ຕ້ອງການຄວາມໝັ້ນໃຈ.','Columns' => 'ຖັນ','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'ຮູບແບບທົ່ວໄປສຳລັບຂັ້ນຕອນການຈ່າຍເງິນ, ສະຫຼຸບການສັ່ງຊື້ ແລະ ພາກສ່ວນອື່ນໆ. ໃຊ້ໄດ້ກັບໜ້າການຈ່າຍເງິນອື່ນໆ, ກະຕ່າສິນຄ້າ, ຄຳຂອບໃຈ (ໄດ້ຮັບຄຳສັ່ງຊື້ແລ້ວ), ແລະ ເບິ່ງໜ້າການສັ່ງຊື້.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'ເມື່ອໃຊ້ຮູບແບບ <em>&quot;1 ຖັນ&quot;</em> ກັບແມ່ແບບການອອກແບບ <em>&quot;ແຍກ&quot;</em> , ຖັນເບື້ອງຂວາຈະສະແດງພຽງແຕ່ຖ້າພື້ນທີ່ວິດເຈັດແຖບດ້ານຂ້າງຂອງໜ້າມີການເຄື່ອນໄຫວຢູ່ (ແຖບດ້ານຂ້າງ Checkout, ແຖບດ້ານຂ້າງ Cart, ຫຼື ແຖບດ້ານຂ້າງ Order Received). ຖ້າບໍ່ດັ່ງນັ້ນໜ້າຈະຍັງຄົງເປັນຖັນດຽວທີ່ມີຮູບແບບແຍກ.','Split column background' => 'ພື້ນຫຼັງແບ່ງຖັນ','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'ເລືອກສີພື້ນຫຼັງສຳລັບຖັນສຳຮອງແບບແຍກ. ປ່ອຍໃຫ້ວ່າງເພື່ອໃຊ້ສີພື້ນຫຼັງສະຫຼຸບລຳດັບ.','Page templates' => 'ແມ່ແບບໜ້າເວັບ','Checkout template' => 'ແມ່ແບບການຈ່າຍເງິນ','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'ແນະນຳໃຫ້ມີສິ່ງລົບກວນໜ້ອຍລົງໃນເວລາຊຳລະເງິນ. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">ອ່ານການຄົ້ນຄວ້າກ່ຽວກັບການປະຖິ້ມກະຕ່າສິນຄ້າ</a> .','Sticky progress bar' => 'ແຖບຄວາມຄືບໜ້າແບບຕິດ','Progress bar style' => 'ຮູບແບບແຖບຄວາມຄືບໜ້າ','Order totals' => 'ຍອດລວມຄຳສັ່ງຊື້','Background color' => 'ສີພື້ນຫຼັງ','Action link' => 'ລິ້ງການກະທຳ','Mobile order summary' => 'ສະຫຼຸບການສັ່ງຊື້ຜ່ານມືຖື','Mobile initial state' => 'ສະຖານະເບື້ອງຕົ້ນຂອງມືຖື','Enable editing cart items at checkout' => 'ເປີດໃຊ້ການແກ້ໄຂລາຍການໃນກະຕ່າໃນເວລາຊຳລະເງິນ','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ອະນຸຍາດໃຫ້ລູກຄ້າປ່ຽນແປງປະລິມານຜະລິດຕະພັນ ຫຼື ລຶບລາຍການສິນຄ້າອອກໂດຍກົງຢູ່ໜ້າຈ່າຍເງິນ.','Cart item errors' => 'ຂໍ້ຜິດພາດຂອງສິນຄ້າໃນກະຕ່າ','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ໃຊ້ໄດ້ສະເພາະເມື່ອລະຫັດຄູປອງຖືກສະແດງເປັນພາກສ່ວນແຍກຕ່າງຫາກໃນໜ້າຈ່າຍເງິນ ຫຼື ໜ້າກະຕ່າສິນຄ້າ, ແລະ ຖ້າການໃຊ້ລະຫັດຄູປອງຖືກເປີດໃຊ້ງານໃນການຕັ້ງຄ່າ WooCommerce.','Coupon codes position' => 'ຕຳແໜ່ງລະຫັດຄູປອງ','Apply coupon button' => 'ປຸ່ມໃຊ້ຄູປອງ','Select style of the "apply coupon" button.' => 'ເລືອກຮູບແບບຂອງປຸ່ມ &quot;ໃຊ້ຄູປອງ&quot;.','Address line 2' => 'ທີ່ຢູ່ແຖວທີ 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ການຕັ້ງຄ່ານີ້ຖືກແບ່ງປັນລະຫວ່າງພາກສ່ວນຊຳລະເງິນ ແລະ ການຮັບສິນຄ້າໃນທ້ອງຖິ່ນ. ໃນພາກສ່ວນການຮັບສິນຄ້າໃນທ້ອງຖິ່ນ, ມັນຍັງຕັດສິນໃຈວ່າຕົວເລືອກສົ່ງ/ຮັບສິນຄ້າຈະສະແດງຢູ່ພາຍໃນພາກສ່ວນວິທີການຂົນສົ່ງ (ກ່ອນທີ່ຢູ່) ຫຼື ເປັນພາກສ່ວນແຍກຕ່າງຫາກ (ຫຼັງຈາກ).','Customer accounts' => 'ບັນຊີລູກຄ້າ','Guest checkout' => 'ການຈ່າຍເງິນຂອງແຂກ','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'ຕົວເລືອກການຈ່າຍເງິນແບບແຂກ, ການເຂົ້າສູ່ລະບົບ ແລະ ການສ້າງບັນຊີຈາກໜ້າການຕັ້ງຄ່າບັນຊີ WooCommerce. ພວກມັນຖືກຈັດການຢູ່ທີ່ນີ້ເພື່ອຄວາມສະດວກສະບາຍຂອງທ່ານ, ແລະ ດັ່ງນັ້ນທ່ານສາມາດໃຊ້ຄ່າທີ່ແຕກຕ່າງກັນຕາມໂປຣໄຟລ໌ການຕັ້ງຄ່າ.','Allow customers to checkout without an account' => 'ອະນຸຍາດໃຫ້ລູກຄ້າຈ່າຍເງິນໄດ້ໂດຍບໍ່ຕ້ອງມີບັນຊີ','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>ແນະນຳໃຫ້</strong> ລູກຄ້າບໍ່ຖືກຮຽກຮ້ອງໃຫ້ສ້າງບັນຊີ ຫຼື ເຂົ້າສູ່ລະບົບໃນລະຫວ່າງການຊຳລະເງິນ, ເຊິ່ງສາມາດຫຼຸດອັດຕາການປ່ຽນແປງໄດ້.','When disabled, customers must log in or create an account to complete the purchase.' => 'ເມື່ອປິດໃຊ້ງານ, ລູກຄ້າຕ້ອງເຂົ້າສູ່ລະບົບ ຫຼື ສ້າງບັນຊີເພື່ອເຮັດສຳເລັດການຊື້.','Login at checkout' => 'ເຂົ້າສູ່ລະບົບຕອນຈ່າຍເງິນ','Enable log-in during checkout' => 'ເປີດໃຊ້ການເຂົ້າສູ່ລະບົບໃນລະຫວ່າງການຈ່າຍເງິນ','Show a link for returning customers to log in from the checkout page.' => 'ສະແດງລິ້ງສຳລັບລູກຄ້າທີ່ກັບມາໃຊ້ບໍລິການເພື່ອເຂົ້າສູ່ລະບົບຈາກໜ້າຈ່າຍເງິນ.','Account creation' => 'ການສ້າງບັນຊີ','Allow customers to create an account during checkout' => 'ອະນຸຍາດໃຫ້ລູກຄ້າສ້າງບັນຊີໃນລະຫວ່າງການຈ່າຍເງິນ','Customers can create an account before placing their order.' => 'ລູກຄ້າສາມາດສ້າງບັນຊີກ່ອນສັ່ງຊື້ໄດ້.','Allow customers to create an account from the My account page' => 'ອະນຸຍາດໃຫ້ລູກຄ້າສ້າງບັນຊີຈາກໜ້າບັນຊີຂອງຂ້ອຍ','Customers can register a new account from the My account page.' => 'ລູກຄ້າສາມາດລົງທະບຽນບັນຊີໃໝ່ໄດ້ຈາກໜ້າບັນຊີຂອງຂ້ອຍ.','Username' => 'ຊື່ຜູ້ໃຊ້','Generate from customer\'s name' => 'ສ້າງຈາກຊື່ລູກຄ້າ','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>ແນະນຳໃຫ້</strong> ລູກຄ້າເລືອກຊື່ຜູ້ໃຊ້ໃນລະຫວ່າງການຈ່າຍເງິນ ເຊິ່ງສາມາດຫຼຸດອັດຕາການປ່ຽນແປງໄດ້.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'ຊື່ຜູ້ໃຊ້ແມ່ນສ້າງຂຶ້ນຈາກຊື່ລູກຄ້າ ຫຼື ຈາກທີ່ຢູ່ອີເມວເມື່ອບໍ່ສາມາດໃຊ້ຊື່ໄດ້.','Password' => 'ລະຫັດຜ່ານ','Send password setup link' => 'ສົ່ງລິ້ງຕັ້ງຄ່າລະຫັດຜ່ານ','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>ແນະນຳໃຫ້</strong> ລູກຄ້າບໍ່ຕ້ອງຕັ້ງລະຫັດຜ່ານໃນລະຫວ່າງການຊຳລະເງິນ ເຊິ່ງສາມາດຫຼຸດອັດຕາການປ່ຽນແປງໄດ້.','Customers receive an email to create their password securely.' => 'ລູກຄ້າໄດ້ຮັບອີເມວເພື່ອສ້າງລະຫັດຜ່ານຂອງເຂົາເຈົ້າຢ່າງປອດໄພ.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'ໃຫ້ລູກຄ້າທີ່ລົງທະບຽນແລ້ວສາມາດຊຳລະເງິນໄດ້ໂດຍບໍ່ຕ້ອງເຂົ້າສູ່ລະບົບ ແລະ ເຊື່ອມໂຍງຄຳສັ່ງຊື້ກັບບັນຊີທີ່ມີຢູ່ແລ້ວຂອງເຂົາເຈົ້າເມື່ອລາຍລະອຽດການຕິດຕໍ່ກົງກັນ.','Existing account message' => 'ຂໍ້ຄວາມບັນຊີທີ່ມີຢູ່ແລ້ວ','Let customers create an account after placing their order, from the thank you page.' => 'ໃຫ້ລູກຄ້າສ້າງບັນຊີຫຼັງຈາກວາງຄໍາສັ່ງຊື້ຂອງເຂົາເຈົ້າແລ້ວ, ຈາກໜ້າຂອບໃຈ.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'ຕົວເລືອກຕ່າງໆໃນພາກນີ້ມີໃຫ້ໃຊ້ເມື່ອການຊຳລະເງິນແບບແຂກ ແລະ ການຈັບຄູ່ບັນຊີຖືກເປີດໃຊ້ງານ. ເປີດໃຊ້ຄຸນສົມບັດທັງສອງຂ້າງເທິງເພື່ອຕັ້ງຄ່າການສ້າງບັນຊີທີ່ຊັກຊ້າ.','Enable delayed account creation' => 'ເປີດໃຊ້ການສ້າງບັນຊີທີ່ຊັກຊ້າ','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'ເປີດໃຊ້ການສ້າງບັນຊີທີ່ຊັກຊ້າເມື່ອທັງການຈ່າຍເງິນແບບແຂກ ແລະ ການຈັບຄູ່ບັນຊີຖືກເປີດໃຊ້ງານ.','Section position' => 'ຕຳແໜ່ງຂອງພາກສ່ວນ','Before customer details section' => 'ກ່ອນພາກສ່ວນລາຍລະອຽດຂອງລູກຄ້າ','After customer details section' => 'ຫຼັງຈາກພາກສ່ວນລາຍລະອຽດລູກຄ້າ','Account creation benefits' => 'ຜົນປະໂຫຍດຂອງການສ້າງບັນຊີ','Leaving the field empty will display the default text.' => 'ການປ່ອຍໃຫ້ຊ່ອງນີ້ວ່າງໄວ້ຈະສະແດງຂໍ້ຄວາມເລີ່ມຕົ້ນ.','Inline buttons' => 'ປຸ່ມໃນແຖວ','Required fields' => 'ຕ້ອງຕື່ມຂໍ້ມູນໃສ່ຊ່ອງ','Enable gift message fields at checkout' => 'ເປີດໃຊ້ຊ່ອງຂໍ້ຄວາມຂອງຂວັນໃນເວລາຊຳລະເງິນ','Expanded gift message' => 'ຂໍ້ຄວາມຂອງຂວັນທີ່ຂະຫຍາຍອອກ','Display gift message field always expanded' => 'ສະແດງຊ່ອງຂໍ້ຄວາມຂອງຂວັນທີ່ຂະຫຍາຍອອກສະເໝີ','Gift message in order details' => 'ຂໍ້ຄວາມຂອງຂວັນໃນລາຍລະອຽດການສັ່ງຊື້','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'ບໍ່ມີການເຊື່ອມໂຍງທີ່ສາມາດໃຊ້ໄດ້ໃນຂະນະນີ້ໃນພາກນີ້. ຕົວເລືອກທີ່ກ່ຽວຂ້ອງກັບແຕ່ລະປລັກອິນ ແລະ ຮູບແບບຈະປາກົດຢູ່ທີ່ນີ້ເມື່ອປລັກອິນ ຫຼື ຮູບແບບນັ້ນຖືກເປີດໃຊ້ງານເທົ່ານັ້ນ.','Phone fields' => 'ຊ່ອງໂທລະສັບ','Field visibility' => 'ການເບິ່ງເຫັນພາກສະໜາມ','Field position' => 'ຕຳແໜ່ງພາກສະໜາມ','Phone country code & validation' => 'ລະຫັດປະເທດໂທລະສັບ ແລະ ການກວດສອບຄວາມຖືກຕ້ອງ','Country' => 'ປະເທດ','Enable country on phone fields' => 'ເປີດໃຊ້ປະເທດໃນຊ່ອງໂທລະສັບ','Filter countries for shipping or billing' => 'ກັ່ນຕອງປະເທດສຳລັບການຂົນສົ່ງ ຫຼື ການຮຽກເກັບເງິນ','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'ຈຳກັດຕົວເລືອກປະເທດໃນແຕ່ລະຊ່ອງເບີໂທລະສັບໃຫ້ເປັນປະເທດທີ່ອະນຸຍາດໃຫ້ຈັດສົ່ງ ຫຼື ຮຽກເກັບເງິນໃນຮ້ານຂອງທ່ານ.','Validation' => 'ການກວດສອບຄວາມຖືກຕ້ອງ','Enable simple validation based on country rules' => 'ເປີດໃຊ້ງານການກວດສອບຄວາມຖືກຕ້ອງແບບງ່າຍໆໂດຍອີງໃສ່ກົດລະບຽບຂອງປະເທດ','Checks that the phone number is valid for the selected country, including country code and length.' => 'ກວດສອບວ່າເບີໂທລະສັບນັ້ນຖືກຕ້ອງສຳລັບປະເທດທີ່ເລືອກ, ລວມທັງລະຫັດປະເທດ ແລະ ຄວາມຍາວ.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'ກວດສອບຢ່າງເຂັ້ມງວດວ່າເບີໂທລະສັບນັ້ນເປັນເບີມືຖື, ເບີຕັ້ງໂຕະ ຫຼື ປະເພດອື່ນທີ່ຍອມຮັບໄດ້ສຳລັບປະເທດທີ່ເລືອກ. ເບີບາງເບີອາດຈະຖືກປະຕິເສດ.','Validation types' => 'ປະເພດການກວດສອບຄວາມຖືກຕ້ອງ','Placeholders' => 'ຕົວຍຶດຕຳແໜ່ງ','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'ບໍ່ມີລະຫັດໃບອະນຸຍາດໃຫ້ຈັດການໃນເວລານີ້. ລະຫັດໃບອະນຸຍາດຈະປາກົດຢູ່ບ່ອນນີ້ເມື່ອປລັກອິນ ຫຼື ແອດອອນ Fluid Checkout ທີ່ໄດ້ຮັບອະນຸຍາດເປີດໃຊ້ງານຢູ່.','Default delivery type' => 'ປະເພດການຈັດສົ່ງເລີ່ມຕົ້ນ','Choose which delivery type will be selected by default.' => 'ເລືອກປະເພດການຈັດສົ່ງທີ່ຈະຖືກເລືອກຕາມຄ່າເລີ່ມຕົ້ນ.','Shipping zone fields' => 'ພື້ນທີ່ເຂດຂົນສົ່ງ','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'ເລືອກຊ່ອງຂໍ້ມູນທີ່ຈະສະແດງສຳລັບຊ່ອງຂໍ້ມູນການກັ່ນຕອງເຂດຈັດສົ່ງສິນຄ້າຮັບເອງໃນທ້ອງຖິ່ນ. ປ່ອຍໃຫ້ວ່າງເພື່ອສະແດງຕົວເລືອກທີ່ມີຢູ່ທັງໝົດ.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'ຊ່ອງຂໍ້ມູນເຫຼົ່ານີ້ຈະຖືກສະແດງເປັນຕົວກອງສຳລັບວິທີການຈັດສົ່ງແບບຮັບເອງໃນທ້ອງຖິ່ນ. ບາງຊ່ອງຂໍ້ມູນອາດຈະຍັງປາກົດຢູ່ໃນຕອນຊຳລະເງິນເມື່ອບໍ່ໄດ້ເລືອກຢູ່ທີ່ນີ້, ຖ້າປລັກອິນທີ່ເຂົ້າກັນໄດ້ຕ້ອງການໃຫ້ພວກມັນເຮັດວຽກຢ່າງຖືກຕ້ອງ.','Order shipping address' => 'ສັ່ງຊື້ທີ່ຢູ່ຈັດສົ່ງ','Order pay page optimization' => 'ການເພີ່ມປະສິດທິພາບໜ້າການຈ່າຍເງິນສັ່ງຊື້','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'ໃຫ້ຮູບແບບທີ່ຊັດເຈນ ແລະ ເນັ້ນໃສ່ການປ່ຽນໃຈເຫລື້ອມໃສຄືກັນກັບການຊຳລະເງິນສຳລັບການສັ່ງຊື້ທີ່ຍັງບໍ່ໄດ້ຈ່າຍ.','Optimize the layout of the order pay page for orders pending payment.' => 'ເພີ່ມປະສິດທິພາບຮູບແບບຂອງໜ້າຈ່າຍເງິນສຳລັບການສັ່ງຊື້ທີ່ຍັງຄ້າງຢູ່.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ຈັບຄູ່ປະສົບການການຈ່າຍເງິນຕາມການສັ່ງຊື້ກັບການຈ່າຍເງິນຂອງທ່ານ ເພື່ອໃຫ້ການເດີນທາງການຊື້ມີຄວາມສອດຄ່ອງ.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'ເພີ່ມສັນຍາລັກ ແລະ ປ້າຍຄວາມໄວ້ວາງໃຈບ່ອນທີ່ຜູ້ຊື້ຕ້ອງການຄວາມໝັ້ນໃຈກ່ອນທີ່ຈະຈ່າຍເງິນ.','Thank you page optimization' => 'ຂອບໃຈການເພີ່ມປະສິດທິພາບໜ້າເວັບ','Make the thank you page and order details clearer for customers after they buy.' => 'ເຮັດໃຫ້ໜ້າຂອບໃຈ ແລະ ລາຍລະອຽດການສັ່ງຊື້ຈະແຈ້ງຂຶ້ນສຳລັບລູກຄ້າຫຼັງຈາກທີ່ເຂົາເຈົ້າຊື້.','Optimize the thank you page and account order details with a clearer layout.' => 'ເພີ່ມປະສິດທິພາບໜ້າຂອບໃຈ ແລະ ລາຍລະອຽດການສັ່ງຊື້ບັນຊີດ້ວຍຮູບແບບທີ່ຊັດເຈນກວ່າ.','Show order status progress, actions, downloads, and notes where they make sense.' => 'ສະແດງຄວາມຄືບໜ້າຂອງສະຖານະການສັ່ງຊື້, ການກະທຳ, ການດາວໂຫຼດ ແລະ ບັນທຶກຕ່າງໆທີ່ເຂົ້າໃຈໄດ້.','Customize order details sections on email notifications.' => 'ປັບແຕ່ງພາກສ່ວນລາຍລະອຽດການສັ່ງຊື້ໃນການແຈ້ງເຕືອນທາງອີເມວ.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'ເພີ່ມສັນຍາລັກ ແລະ ປ້າຍຄວາມໄວ້ວາງໃຈບ່ອນທີ່ຜູ້ຊື້ຕ້ອງການຄວາມໝັ້ນໃຈຫຼັງຈາກການຊື້.','Email notifications' => 'ການແຈ້ງເຕືອນທາງອີເມວ','Enable thank you page and order details optimizations to see more options' => 'ເປີດໃຊ້ໜ້າຂອບໃຈ ແລະ ການເພີ່ມປະສິດທິພາບລາຍລະອຽດການສັ່ງຊື້ເພື່ອເບິ່ງຕົວເລືອກເພີ່ມເຕີມ','Use wide layout on thank you page' => 'ໃຊ້ຮູບແບບກວ້າງໃນໜ້າຂອບໃຈ','These options affect the thank you page, view order details on account pages and on email notifications.' => 'ຕົວເລືອກເຫຼົ່ານີ້ມີຜົນກະທົບຕໍ່ໜ້າຂອບໃຈ, ເບິ່ງລາຍລະອຽດການສັ່ງຊື້ໃນໜ້າບັນຊີ ແລະ ໃນການແຈ້ງເຕືອນທາງອີເມວ.','Save settings' => 'ບັນທຶກການຕັ້ງຄ່າ','Docs' => 'ເອກະສານ','Cart' => 'ກະຕ່າ','Thank you' => 'ຂອບໃຈ','Address autocomplete' => 'ການຕື່ມຂໍ້ມູນທີ່ຢູ່ໂດຍອັດຕະໂນມັດ','Trust badges' => 'ປ້າຍຄວາມໄວ້ວາງໃຈ','You do not have permission to save these settings.' => 'ທ່ານບໍ່ມີສິດໃນການບັນທຶກການຕັ້ງຄ່າເຫຼົ່ານີ້.','Invalid save request.' => 'ຄຳຮ້ອງຂໍບັນທຶກບໍ່ຖືກຕ້ອງ.','Your settings have been saved.' => 'ການຕັ້ງຄ່າຂອງທ່ານໄດ້ຖືກບັນທຶກໄວ້ແລ້ວ.','Saving...' => 'ກຳລັງບັນທຶກ...','Settings could not be saved. Please try again.' => 'ບໍ່ສາມາດບັນທຶກການຕັ້ງຄ່າໄດ້. ກະລຸນາລອງໃໝ່ອີກຄັ້ງ.','Dismiss notice' => 'ປິດແຈ້ງການ','Open settings menu' => 'ເປີດເມນູການຕັ້ງຄ່າ','Close settings menu' => 'ປິດເມນູການຕັ້ງຄ່າ','Preview' => 'ຕົວຢ່າງ','Expand preview' => 'ຂະຫຍາຍຕົວຢ່າງ','Collapse preview' => 'ຫຍໍ້ຕົວຢ່າງ','Show header and footer' => 'ສະແດງຫົວຂໍ້ ແລະ ສ່ວນທ້າຍ','Hide header and footer' => 'ເຊື່ອງຫົວຂໍ້ ແລະ ສ່ວນທ້າຍ','Page preview' => 'ຕົວຢ່າງໜ້າ','Preview viewport' => 'ສະແດງຕົວຢ່າງວິວພອດ','Tablet' => 'ແທັບເລັດ','Desktop' => 'ເດັສທັອບ','Preview width' => 'ຄວາມກວ້າງຂອງຕົວຢ່າງ','Decrease width' => 'ຫຼຸດຄວາມກວ້າງ','Preview width in pixels' => 'ຄວາມກວ້າງຂອງຕົວຢ່າງເປັນພິກເຊວ','Increase width' => 'ເພີ່ມຄວາມກວ້າງ','Preview as' => 'ສະແດງຕົວຢ່າງເປັນ','Guest' => 'ແຂກ','Logged in' => 'ເຂົ້າສູ່ລະບົບແລ້ວ','Preview page' => 'ສະແດງຕົວຢ່າງໜ້າ','Expand preview for a closer look' => 'ຂະຫຍາຍຕົວຢ່າງເພື່ອເບິ່ງໃກ້ໆ','Available with %s.' => 'ມີໃຫ້ໃຊ້ກັບ %s.','Turn them on' => 'ເປີດພວກມັນ','Optimizations for this page are turned off. %s to preview the page.' => 'ການເພີ່ມປະສິດທິພາບສຳລັບໜ້ານີ້ຖືກປິດໄວ້. %s ເພື່ອເບິ່ງຕົວຢ່າງໜ້າ.','%s preview' => 'ຕົວຢ່າງ %s','Isolated session · nothing is saved' => 'ກອງປະຊຸມແຍກຕ່າງຫາກ · ບໍ່ມີຫຍັງຖືກບັນທຶກໄວ້','Usage tracking' => 'ການຕິດຕາມການນຳໃຊ້','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'ສົ່ງລາຍງານສະພາບແວດລ້ອມເວັບໄຊທ໌ທີ່ບໍ່ລະອຽດອ່ອນເພື່ອຊ່ວຍໃຫ້ Fluid Checkout ປັບປຸງຄວາມເຂົ້າກັນໄດ້. ລາຍງານຈະບໍ່ຖືກສົ່ງຈົນກວ່າຈະເປີດໃຊ້ໃນຕົວເລືອກຂ້າງລຸ່ມນີ້.','Send usage tracking reports to Fluid Checkout' => 'ສົ່ງລາຍງານການຕິດຕາມການນຳໃຊ້ໄປຫາ Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'ບົດລາຍງານເຫຼົ່ານີ້ຊ່ວຍພວກເຮົາປັບປຸງຄວາມເຂົ້າກັນໄດ້ ແລະ ການສະໜັບສະໜູນເວັບໄຊທ໌ຂອງທ່ານ ແລະ ຈະຖືກສົ່ງໄປທຸກໆອາທິດເມື່ອເປີດໃຊ້ງານ.','No customer, admin user, or any other sensitive data is included in the reports.' => 'ບໍ່ມີລູກຄ້າ, ຜູ້ໃຊ້ທີ່ເບິ່ງແຍງລະບົບ ຫຼື ຂໍ້ມູນທີ່ລະອຽດອ່ອນອື່ນໆທີ່ລວມຢູ່ໃນລາຍງານ.','Basic environment info' => 'ຂໍ້ມູນພື້ນຖານກ່ຽວກັບສະພາບແວດລ້ອມ','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'ຂໍ້ມູນລາຍຊື່ WordPress, PHP, WooCommerce, ຮູບແບບ ແລະ ປລັກອິນ. ລວມຢູ່ສະເໝີເມື່ອເປີດໃຊ້ການລາຍງານ. ຊ່ວຍໃຫ້ພວກເຮົາເຂົ້າໃຈສະພາບແວດລ້ອມທີ່ເວັບໄຊທ໌ຂອງທ່ານກຳລັງເຮັດວຽກຢູ່.','Plugin settings' => 'ການຕັ້ງຄ່າປລັກອິນ','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'ສົ່ງການຕັ້ງຄ່າປລັກອິນ Fluid Checkout ເພື່ອຊ່ວຍໃນການຮ້ອງຂໍການຊ່ວຍເຫຼືອ ແລະ ຊ່ວຍພວກເຮົາເຂົ້າໃຈວ່າທ່ານກຳລັງໃຊ້ປລັກອິນຂອງພວກເຮົາແນວໃດ.','Coming soon' => 'ກຳລັງຈະມາຮອດໃນໄວໆນີ້','Sales metrics' => 'ຕົວຊີ້ວັດການຂາຍ','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'ຈຳນວນການສັ່ງຊື້ປະຈຳເດືອນ ແລະ ຍອດຂາຍທັງໝົດສຳລັບໜຶ່ງປີກ່ອນການຕິດຕັ້ງ Fluid Checkout ຈົນເຖິງມື້ນີ້. ຊ່ວຍໃຫ້ພວກເຮົາເຂົ້າໃຈວ່າທ່ານກຳລັງຫາເງິນໄດ້ຫຼາຍຂຶ້ນດ້ວຍການຕິດຕັ້ງປລັກອິນຂອງພວກເຮົາຫຼືບໍ່. ຈະບໍ່ມີການສົ່ງຂໍ້ມູນລູກຄ້າ ຫຼື ຜູ້ໃຊ້ໃດໆ.','Utilities' => 'ສາທາລະນູປະໂພກ','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'ໃຊ້ອົງປະກອບເລື່ອນລົງ <code>TomSelect</code> ແທນ <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect ເປັນອົງປະກອບການເລືອກແບບເລື່ອນລົງທີ່ງ່າຍກວ່າເຊິ່ງມີຄວາມສ່ຽງຕໍ່ການຜິດພາດໜ້ອຍກວ່າ Select2, ໃນຂະນະທີ່ສະເໜີໜ້າທີ່ດຽວກັນ.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'ກຳນົດຂະໜາດຕົວອັກສອນພາຍໃນຊ່ອງຂໍ້ມູນແບບຟອມເປັນ 16px ໃນໜ້າເວັບທີ່ໄດ້ຮັບການປັບປຸງໃຫ້ດີທີ່ສຸດໂດຍປລັກອິນນີ້ ເພື່ອຫຼີກເວັ້ນການຊູມເຂົ້າໂດຍອັດຕະໂນມັດເມື່ອພົວພັນກັບຊ່ອງຂໍ້ມູນແບບຟອມໃນອຸປະກອນຂະໜາດນ້ອຍ.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari ແລະໂປຣແກຣມທ່ອງເວັບອື່ນໆອາດຈະຊູມເຂົ້າໂດຍອັດຕະໂນມັດໃນອຸປະກອນມືຖືເພື່ອເຮັດໃຫ້ຂໍ້ຄວາມອ່ານງ່າຍຂຶ້ນເມື່ອຂະໜາດຕົວອັກສອນນ້ອຍກວ່າ 16px.','Enable script processing tracking on the browser console.' => 'ເປີດໃຊ້ການຕິດຕາມການປະມວນຜົນສະຄຣິບໃນຄອນໂຊນບຣາວເຊີ.','Unminified assets' => 'ຊັບສິນທີ່ບໍ່ໄດ້ລະບຸ','Google Maps scripts' => 'ສະຄຣິບ Google Maps','Do not remove duplicate Google Maps scripts' => 'ຢ່າລຶບສະຄຣິບ Google Maps ທີ່ຊໍ້າກັນອອກ','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'ເມື່ອເປີດໃຊ້ງານແລ້ວ, ສະຄຣິບ Google Maps ທີ່ຊໍ້າກັນຈະບໍ່ຖືກລຶບອອກ ເຊິ່ງສາມາດເຮັດໃຫ້ເກີດຄວາມຜິດພາດ ແລະ ບັນຫາປະສິດທິພາບ. ໃຫ້ໃຊ້ຕົວເລືອກນີ້ສະເພາະໃນຂະນະທີ່ແກ້ໄຂບັນຫາເທົ່ານັ້ນ.','Widget areas' => 'ພື້ນທີ່ວິດເຈັດ','Last step on mobile' => 'ຂັ້ນຕອນສຸດທ້າຍໃນມືຖື','Display widgets only at last step on mobile' => 'ສະແດງວິດເຈັດສະເພາະໃນຂັ້ນຕອນສຸດທ້າຍໃນມືຖືເທົ່ານັ້ນ','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'ສະແດງວິດເຈັດເຄື່ອງໝາຍຄວາມໄວ້ວາງໃຈໃນການຈ່າຍເງິນເທົ່ານັ້ນເມື່ອເບິ່ງຂັ້ນຕອນການຈ່າຍເງິນສຸດທ້າຍໃນອຸປະກອນມືຖື','Standard' => 'ມາດຕະຖານ','VAT number field' => 'ຊ່ອງຂໍ້ມູນເລກທີ່ VAT','Add a VAT number field to the billing form.' => 'ໃຫ້ເພີ່ມຊ່ອງຂໍ້ມູນໝາຍເລກ VAT ໃສ່ແບບຟອມການຮຽກເກັບເງິນ.','Field label' => 'ປ້າຍຊື່ຊ່ອງຂໍ້ມູນ','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'ຕັ້ງປ້າຍຊື່ໃຫ້ກັບຊ່ອງຂໍ້ມູນໝາຍເລກ VAT (ເຊັ່ນ: ໝາຍເລກ VAT). ໃນເວັບໄຊທ໌ຫຼາຍພາສາ, ມັນດີກວ່າທີ່ຈະປ່ອຍໃຫ້ຊ່ອງນີ້ວ່າງໄວ້ ແລະ ແປສະຕຣິງຕົ້ນສະບັບ.','VAT Number' => 'ເລກທີ່ VAT','EU-VAT' => 'EU-ພາສີມູນຄ່າເພີ່ມ','Enable the VAT number field to see more options' => 'ເປີດໃຊ້ຊ່ອງຂໍ້ມູນເລກທະບຽນພາສີມູນຄ່າເພີ່ມເພື່ອເບິ່ງຕົວເລືອກເພີ່ມເຕີມ','VAT validation' => 'ການກວດສອບມູນຄ່າເພີ່ມ','Validate VAT number field for EU-VAT during checkout' => 'ກວດສອບຊ່ອງຂໍ້ມູນໝາຍເລກ VAT ສຳລັບ EU-VAT ໃນລະຫວ່າງການຊຳລະເງິນ','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'ກວດສອບວ່າເລກທີ່ VAT ທີ່ໃຫ້ມານັ້ນເປັນເລກທີ່ VAT ທີ່ຖືກຕ້ອງທີ່ລົງທະບຽນຢູ່ໃນຖານຂໍ້ມູນ VIES ຂອງເອີຣົບ (ລະບົບແລກປ່ຽນຂໍ້ມູນ VAT).','Shop VAT number' => 'ເລກທີ່ VAT ຂອງຮ້ານຄ້າ','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'ເລກທີ່ VAT ຂອງຮ້ານທີ່ໃຊ້ສຳລັບການຮ້ອງຂໍການຢືນຢັນ EU-VAT ແລະພິມຢູ່ໃນໃບແຈ້ງໜີ້.<br> <strong>ພວກເຮົາຂໍແນະນຳໃຫ້ເພີ່ມເລກທະບຽນພາສີມູນຄ່າເພີ່ມຂອງຮ້ານຄ້າຂອງທ່ານ</strong> ຖ້າບໍ່ດັ່ງນັ້ນຜົນການປຶກສາຫາລືຂອງ VIES ອາດຈະບໍ່ຖືກຕ້ອງສຳລັບຈຸດປະສົງດ້ານບັນຊີ.<br> ເຊັ່ນ: <code>ATU99999999</code> ຫຼື <code>EE999999999</code> .','Reverse charge' => 'ການສາກໄຟແບບປີ້ນກັບກັນ','Apply reverse charge mechanism' => 'ນຳໃຊ້ກົນໄກການສາກໄຟແບບປີ້ນກັບກັນ','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'ຕັ້ງອັດຕາພາສີເປັນສູນ ແລະ ສະແດງ &quot;ການຄິດຄ່າທຳນຽມຍ້ອນກັບ&quot; ໃນໃບແຈ້ງໜີ້ເມື່ອເລກທີ່ VAT ຂອງລູກຄ້າຖືກຕ້ອງ. ອາດຈະຕ້ອງມີຂໍ້ຄວາມ &quot;ການຄິດຄ່າທຳນຽມຍ້ອນກັບ&quot; ທີ່ແຕກຕ່າງກັນຂຶ້ນກັບປະເທດຂອງຮ້ານ.','Same country' => 'ປະເທດດຽວກັນ','Apply reverse charge mechanism for transactions in the shop country:' => 'ນຳໃຊ້ກົນໄກການຄິດຄ່າທຳນຽມແບບປີ້ນກັບກັນສຳລັບທຸລະກຳໃນປະເທດຮ້ານຄ້າ:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'ເປີດໃຊ້ກົນໄກການຄິດຄ່າທຳນຽມແບບປີ້ນກັບກັນສຳລັບທຸລະກຳລະຫວ່າງບໍລິສັດໃນປະເທດດຽວກັນກັບຮ້ານຄ້າ.','Reverse charge exceptions' => 'ຂໍ້ຍົກເວັ້ນການຄິດຄ່າທຳນຽມປີ້ນກັບກັນ','Select additional countries to skip applying the reverse charge mechanism.' => 'ເລືອກປະເທດເພີ່ມເຕີມເພື່ອຂ້າມການນຳໃຊ້ກົນໄກການຄິດຄ່າທຳນຽມແບບປີ້ນກັບກັນ.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'ພາສີຈະຖືກຄິດຄ່າທຳນຽມຈາກການສັ່ງຊື້ຈາກບັນດາປະເທດເຫຼົ່ານີ້ເຖິງແມ່ນວ່າຈະມີການສະໜອງເລກທີ່ VAT ທີ່ຖືກຕ້ອງກໍຕາມ.','Reverse charge label on invoices' => 'ປ້າຍກຳກັບຄ່າບໍລິການແບບປີ້ນກັບກັນໃນໃບແຈ້ງໜີ້','Set the label of "reverse charge" on the checkout page and order details.' => 'ຕັ້ງປ້າຍ &quot;ການຮຽກເກັບເງິນກັບຄືນ&quot; ໃນໜ້າຈ່າຍເງິນ ແລະ ລາຍລະອຽດການສັ່ງຊື້.','Reverse charge text on invoices' => 'ຂໍ້ຄວາມກ່ຽວກັບຄ່າທຳນຽມປີ້ນກັບກັນໃນໃບແຈ້ງໜີ້','Set the label of "reverse charge" text on invoices.' => 'ຕັ້ງປ້າຍກຳກັບຂໍ້ຄວາມ &quot;ການຮຽກເກັບເງິນຍ້ອນກັບ&quot; ໃນໃບແຈ້ງໜີ້.','Tax to be paid on reverse charge basis' => 'ພາສີທີ່ຕ້ອງຈ່າຍໂດຍອີງໃສ່ການຄິດໄລ່ຄ່າທຳນຽມຍ້ອນກັບ','Company name' => 'ຊື່ບໍລິສັດ','Autocomplete company name from VAT number' => 'ຕື່ມຂໍ້ມູນຊື່ບໍລິສັດໂດຍອັດຕະໂນມັດຈາກເລກທີ່ VAT','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ຕື່ມຂໍ້ມູນໃສ່ຊື່ບໍລິສັດທີ່ຮຽກເກັບເງິນໂດຍອີງໃສ່ເລກທີ່ VAT ທີ່ຖືກຕ້ອງທີ່ລູກຄ້າໃຫ້.','Company name editing' => 'ການແກ້ໄຂຊື່ບໍລິສັດ','Allow editing of auto-filled company name' => 'ອະນຸຍາດໃຫ້ແກ້ໄຂຊື່ບໍລິສັດທີ່ຕື່ມຂໍ້ມູນອັດຕະໂນມັດ','When enabled, customers can change the company name associated with the provided VAT number.' => 'ເມື່ອເປີດໃຊ້ງານແລ້ວ, ລູກຄ້າສາມາດປ່ຽນຊື່ບໍລິສັດທີ່ກ່ຽວຂ້ອງກັບເລກທີ່ VAT ທີ່ສະໜອງໃຫ້ໄດ້.','EU-VAT for digital goods' => 'EU-VAT ສຳລັບສິນຄ້າດິຈິຕອນ','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'ນັບຕັ້ງແຕ່ວັນທີ 1 ມັງກອນ 2015 ເປັນຕົ້ນໄປ, ໄດ້ມີການດັດແປງກົດລະບຽບ VAT ຂອງ EU ກ່ຽວກັບສິນຄ້າດິຈິຕອນ, ເຊິ່ງສົ່ງຜົນກະທົບຕໍ່ທຸລະກຳ B2C ເທົ່ານັ້ນ. VAT ຂອງສິນຄ້າດິຈິຕອນຕ້ອງໄດ້ຄິດໄລ່ໂດຍອີງໃສ່ສະຖານທີ່ຂອງລູກຄ້າ, ແລະ ຕ້ອງມີການເກັບກຳຫຼັກຖານຂອງເລື່ອງນີ້ (ທີ່ຢູ່ IP ແລະ ທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນ).','Tax classes for digital goods' => 'ໝວດພາສີສຳລັບສິນຄ້າດິຈິຕອນ','Select some tax classes' => 'ເລືອກບາງປະເພດພາສີ','Location evidence' => 'ຫຼັກຖານສະຖານທີ່','Collect customer\'s location evidence' => 'ເກັບກຳຫຼັກຖານສະຖານທີ່ຂອງລູກຄ້າ','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'ບັນທຶກທີ່ຢູ່ IP ແລະກວດສອບຄວາມຖືກຕ້ອງກັບທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນຂອງລູກຄ້າ. ລູກຄ້າຕ້ອງຢືນຢັນທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນຂອງເຂົາເຈົ້າໂດຍການໝາຍຕິກໃສ່ກ່ອງກາເຄື່ອງໝາຍໃນໜ້າຊຳລະເງິນ ຖ້າປະເທດຈາກທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນ ແລະ IP ຂອງເຂົາເຈົ້າບໍ່ກົງກັນ.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ຕົວເລືອກນີ້ຖືກຈັດການໃນ Fluid Checkout. <a href="%s">ປ່ຽນມັນໄດ້ໃນການຕັ້ງຄ່າບັນຊີລູກຄ້າ</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ຕົວເລືອກນີ້ຖືກຈັດການຢູ່ໃນ Fluid Checkout. ປ່ຽນມັນພາຍໃຕ້ Fluid Checkout &gt; ບັນຊີລູກຄ້າ.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ຕົວເລືອກນີ້ຖືກຈັດການໃນ Fluid Checkout. ຈຸດໝາຍປາຍທາງການຂົນສົ່ງຈະຖືກຕັ້ງເປັນ &quot;ທີ່ຢູ່ເລີ່ມຕົ້ນຂອງລູກຄ້າ&quot; ສະເໝີເມື່ອ Fluid Checkout ຖືກເປີດໃຊ້ງານ. ລູກຄ້າຍັງສາມາດໃຫ້ທີ່ຢູ່ການຂົນສົ່ງ ແລະ ທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນທີ່ແຕກຕ່າງກັນໃນລະຫວ່າງການຊຳລະເງິນໄດ້.<br><br> ຕົວເລືອກສຳລັບການຕັ້ງຄ່າທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນເລີ່ມຕົ້ນໃຫ້ຄືກັນກັບທີ່ຢູ່ຈັດສົ່ງແມ່ນມີຢູ່ໃນ <a href="%s">ການຕັ້ງຄ່າ Fluid Checkout</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ຕົວເລືອກນີ້ຖືກຈັດການໃນ Fluid Checkout. ຈຸດໝາຍປາຍທາງການຂົນສົ່ງຈະຖືກຕັ້ງເປັນ &quot;ຄ່າເລີ່ມຕົ້ນຕາມທີ່ຢູ່ຂົນສົ່ງຂອງລູກຄ້າ&quot; ສະເໝີເມື່ອ Fluid Checkout ຖືກເປີດໃຊ້ງານ. ລູກຄ້າຍັງສາມາດໃຫ້ທີ່ຢູ່ຈັດສົ່ງ ແລະ ທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນທີ່ແຕກຕ່າງກັນໃນລະຫວ່າງການຊຳລະເງິນໄດ້.<br><br> ຕົວເລືອກສຳລັບການຕັ້ງຄ່າທີ່ຢູ່ສຳລັບການຮຽກເກັບເງິນເລີ່ມຕົ້ນໃຫ້ຄືກັນກັບທີ່ຢູ່ຈັດສົ່ງແມ່ນມີຢູ່ໃນ WooCommerce &gt; ການຕັ້ງຄ່າ &gt; Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ການຕັ້ງຄ່າເຫຼົ່ານີ້ໄດ້ຖືກຍ້າຍໄປທີ່ WP Admin &gt; Fluid Checkout &gt; Settings.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ແຖບການຕັ້ງຄ່າ WooCommerce ນີ້ຖືກຍົກເລີກແລ້ວ ແລະ ຈະຖືກລຶບອອກໃນ Fluid Checkout 6.0.','Go to settings page' => 'ໄປທີ່ໜ້າການຕັ້ງຄ່າ','Hide this tab permanently' => 'ເຊື່ອງແຖບນີ້ຢ່າງຖາວອນ','Site report preview' => 'ຕົວຢ່າງລາຍງານເວັບໄຊທ໌','This is the data that would be included in the next site environment report based on your current settings.' => 'ນີ້ແມ່ນຂໍ້ມູນທີ່ຈະຖືກລວມເຂົ້າໃນລາຍງານສະພາບແວດລ້ອມຂອງເວັບໄຊທ໌ຕໍ່ໄປໂດຍອີງໃສ່ການຕັ້ງຄ່າປັດຈຸບັນຂອງທ່ານ.','Loading report preview...' => 'ກຳລັງໂຫຼດຕົວຢ່າງລາຍງານ...','Could not load the site report preview. Try again.' => 'ບໍ່ສາມາດໂຫຼດຕົວຢ່າງລາຍງານເວັບໄຊໄດ້. ລອງໃໝ່ອີກຄັ້ງ.','Could not send the site report. Try again.' => 'ບໍ່ສາມາດສົ່ງລາຍງານເວັບໄຊໄດ້. ລອງໃໝ່ອີກຄັ້ງ.','Site report sent successfully.' => 'ສົ່ງລາຍງານເວັບໄຊທ໌ສຳເລັດແລ້ວ.','Enable and send now' => 'ເປີດໃຊ້ ແລະ ສົ່ງດຽວນີ້','Close' => 'ປິດ','A site report request is already in progress. Try again in a moment.' => 'ການຮ້ອງຂໍລາຍງານເວັບໄຊທ໌ກຳລັງດຳເນີນການຢູ່. ລອງໃໝ່ອີກຄັ້ງໃນອີກບໍ່ດົນ.','Site environment reporting is disabled.' => 'ການລາຍງານສະພາບແວດລ້ອມຂອງເວັບໄຊທ໌ຖືກປິດໃຊ້ງານ.','No site report data is available to send.' => 'ບໍ່ມີຂໍ້ມູນລາຍງານເວັບໄຊທ໌ທີ່ສາມາດສົ່ງໄດ້.','This site domain cannot send environment reports (local or development domains are excluded).' => 'ໂດເມນເວັບໄຊນີ້ບໍ່ສາມາດສົ່ງລາຍງານສະພາບແວດລ້ອມໄດ້ (ຍົກເວັ້ນໂດເມນທ້ອງຖິ່ນ ຫຼື ໂດເມນການພັດທະນາ).','A site report was sent recently. Try again later.' => 'ລາຍງານເວັບໄຊທ໌ໄດ້ຖືກສົ່ງໄປເມື່ອບໍ່ດົນມານີ້. ລອງໃໝ່ໃນພາຍຫຼັງ.','The site report could not be sent. Try again later.' => 'ບໍ່ສາມາດສົ່ງລາຍງານເວັບໄຊທ໌ໄດ້. ລອງໃໝ່ໃນພາຍຫຼັງ.','Site environment reporting is not available.' => 'ການລາຍງານສະພາບແວດລ້ອມຂອງເວັບໄຊທ໌ບໍ່ສາມາດໃຊ້ໄດ້.','No site report data is available for the selected settings.' => 'ບໍ່ມີຂໍ້ມູນລາຍງານເວັບໄຊທ໌ສຳລັບການຕັ້ງຄ່າທີ່ເລືອກ.','You are not allowed to manage site reports.' => 'ທ່ານບໍ່ໄດ້ຮັບອະນຸຍາດໃຫ້ຈັດການລາຍງານເວັບໄຊທ໌.','PRO feature' => 'ຄຸນສົມບັດ PRO','Other plugins' => 'ປລັກອິນອື່ນໆ','Get only this add-on &mdash; %s' => 'ຮັບສະເພາະສ່ວນເສີມນີ້ເທົ່ານັ້ນ — %s','Install add-on' => 'ຕິດຕັ້ງແອດອອນ','Upgrade to PRO &mdash; %s' => 'ອັບເກຣດເປັນ PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">ຮັບ %2$s</a> ເພື່ອປົດລັອກຕົວເລືອກເຫຼົ່ານີ້.','Add-on' => 'ແອດອອນ','View documentation' => 'ເບິ່ງເອກະສານ','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'ການຮ້ອງຂໍຕ້ອງການຜູ້ໃຊ້ WordPress ທີ່ເຂົ້າສູ່ລະບົບແລ້ວ. ຍົກເວັ້ນ user_id ເພື່ອໃຊ້ຂໍ້ມູນຂອງຜູ້ໃຊ້ປັດຈຸບັນ, ຫຼືສົ່ງຕໍ່ user_id ເພື່ອເປົ້າໝາຍບັນຊີອື່ນເມື່ອຜູ້ໂທສາມາດແກ້ໄຂຜູ້ໃຊ້ນັ້ນໄດ້ (ຄວາມສາມາດຂອງ edit_user). ການຮ້ອງຂໍທີ່ບໍ່ໄດ້ຮັບການພິສູດຢືນຢັນຈະສົ່ງຄືນ fc_api_forbidden. user_id ທີ່ບໍ່ຖືກຕ້ອງຈະສົ່ງຄືນ fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 ດ້ວຍ { &quot;data&quot;: { ... } } ເມື່ອ handler ສົ່ງຄືນ payload.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 ດ້ວຍ { &quot;success&quot;: true } ເມື່ອບໍ່ມີ payload (ຕົວຢ່າງ DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'ຄວາມລົ້ມເຫຼວສົ່ງຄືນຂໍ້ຜິດພາດ WordPress REST JSON ຈາກ WP_Error (ລະຫັດ, ຂໍ້ຄວາມ, data.status). ລະຫັດສາຍໃຊ້ຄຳນຳໜ້າ fc_api_*.','Forbidden access.' => 'ການເຂົ້າເຖິງທີ່ຫ້າມ.','Target user was not found.' => 'ບໍ່ພົບຜູ້ໃຊ້ເປົ້າໝາຍ.','This feature is not available.' => 'ຄຸນສົມບັດນີ້ບໍ່ສາມາດໃຊ້ໄດ້.','A required address field is missing.' => 'ບໍ່ມີຊ່ອງທີ່ຢູ່ທີ່ຕ້ອງການ.','Postcode or ZIP is invalid.' => 'ລະຫັດໄປສະນີ ຫຼື ລະຫັດໄປສະນີບໍ່ຖືກຕ້ອງ.','Phone number is invalid.' => 'ເບີໂທລະສັບບໍ່ຖືກຕ້ອງ.','State or county is invalid.' => 'ລັດ ຫຼື ເຂດປົກຄອງບໍ່ຖືກຕ້ອງ.','Country is invalid or has no address fields.' => 'ປະເທດບໍ່ຖືກຕ້ອງ ຫຼື ບໍ່ມີຊ່ອງທີ່ຢູ່.','The request could not be processed.' => 'ບໍ່ສາມາດດຳເນີນການຄຳຮ້ອງຂໍໄດ້.','Back to previous step' => 'ກັບໄປຫາຂັ້ນຕອນກ່ອນໜ້ານີ້','Skip to settings' => 'ຂ້າມໄປຫາການຕັ້ງຄ່າ','Start over and return to the first guided setup step' => 'ເລີ່ມຕົ້ນໃໝ່ ແລະ ກັບຄືນໄປຫາຂັ້ນຕອນການຕັ້ງຄ່າແບບແນະນຳທຳອິດ','Start over' => 'ເລີ່ມຕົ້ນໃໝ່','Please complete all sub-steps before continuing.' => 'ກະລຸນາເຮັດຂັ້ນຕອນຍ່ອຍທັງໝົດໃຫ້ສຳເລັດກ່ອນທີ່ຈະດຳເນີນການຕໍ່ໄປ.','Expand' => 'ຂະຫຍາຍ','Collapse' => 'ຫຍໍ້ລົງ','Skip' => 'ຂ້າມ','Mark as complete' => 'ໝາຍວ່າສຳເລັດແລ້ວ','Mark as incomplete' => 'ໝາຍວ່າຍັງບໍ່ຄົບຖ້ວນ','View full-size image: %s' => 'ເບິ່ງຮູບພາບຂະໜາດເຕັມ: %s','Full-size setup guide image' => 'ຮູບພາບຄູ່ມືການຕັ້ງຄ່າຂະໜາດເຕັມ','Close image' => 'ປິດຮູບພາບ','Fluid Checkout Guided Setup' => 'ການຕັ້ງຄ່າຄູ່ມືການຈ່າຍເງິນແບບໄຫຼ','Welcome' => 'ຍິນດີຕ້ອນຮັບ','Explore your checkout' => 'ສຳຫຼວດການຈ່າຍເງິນຂອງທ່ານ','All set' => 'ທຸກຢ່າງພ້ອມແລ້ວ','You do not have permission to access this page.' => 'ທ່ານບໍ່ມີສິດອະນຸຍາດໃນການເຂົ້າເຖິງໜ້ານີ້.','Go to step %1$d: %2$s' => 'ໄປທີ່ຂັ້ນຕອນ %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ການຕັ້ງຄ່າແບບແນະນຳນີ້ຊ່ວຍໃຫ້ທ່ານຄຸ້ນເຄີຍກັບ Fluid Checkout. ຂັ້ນຕອນຂ້າງລຸ່ມນີ້ແມ່ນຕົວຢ່າງສຳລັບຕອນນີ້.','Continue to the next step when you are ready.' => 'ສືບຕໍ່ຂັ້ນຕອນຕໍ່ໄປເມື່ອທ່ານພ້ອມແລ້ວ.','Open your store checkout to see Fluid Checkout in action.' => 'ເປີດການຈ່າຍເງິນຂອງຮ້ານຂອງທ່ານເພື່ອເບິ່ງການຊຳລະເງິນດ້ວຍ Fluid Checkout ໃນການເຮັດວຽກ.','View checkout page' => 'ເບິ່ງໜ້າຈ່າຍເງິນ','You can return to Fluid Checkout settings to continue configuring your store.' => 'ທ່ານສາມາດກັບຄືນໄປຫາການຕັ້ງຄ່າ Fluid Checkout ເພື່ອສືບຕໍ່ຕັ້ງຄ່າຮ້ານຄ້າຂອງທ່ານໄດ້.','Review checkout and cart settings' => 'ກວດສອບການຕັ້ງຄ່າການຈ່າຍເງິນ ແລະ ກະຕ່າສິນຄ້າ','Explore add-ons from the dashboard' => 'ສຳຫຼວດໂປຣແກຣມເສີມຈາກແຜງຄວບຄຸມ','Finish & go to settings' => 'ສຳເລັດ ແລະ ໄປທີ່ການຕັ້ງຄ່າ','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'ອັບເດດຕົວເລືອກການເບິ່ງເຫັນຊ່ອງເບີໂທລະສັບສຳລັບການຮຽກເກັບເງິນຈາກຄ່າເດີມໃຫ້ກົງກັບສົນທິສັນຍາ WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'ອັບເດດຕົວເລືອກການເບິ່ງເຫັນຊ່ອງເບີໂທລະສັບຂົນສົ່ງຈາກຄ່າເດີມໃຫ້ກົງກັບສົນທິສັນຍາ WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ສຳເນົາການຕັ້ງຄ່າສີພື້ນຫຼັງຂອງສະຫຼຸບຄຳສັ່ງຊື້ໄປໃສ່ຕົວເລືອກສີພື້ນຫຼັງຖັນສຳຮອງແບບແຍກແບບໃໝ່.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'ຄຸນສົມບັດການເລືອກຊ່ອງຂໍ້ມູນທີ່ປັບປຸງແລ້ວຈະຖືກປິດໃຊ້ງານສະເໝີເມື່ອໃຊ້ປລັກອິນ Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ຕຳແໜ່ງການສັ່ງຊື້ຈະຖືກຕັ້ງໄວ້ທີ່ &quot;ຢູ່ລຸ່ມສະຫຼຸບການສັ່ງຊື້&quot; ສະເໝີເມື່ອໃຊ້ German Market. ປລັກອິນນັ້ນຮຽກຮ້ອງໃຫ້ປຸ່ມສັ່ງຊື້ ແລະ ກ່ອງກາເຄື່ອງໝາຍທາງກົດໝາຍສະແດງຢູ່ລຸ່ມສະຫຼຸບການສັ່ງຊື້.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ຕຳແໜ່ງການສັ່ງຊື້ແມ່ນຖືກຕັ້ງໄວ້ທີ່ &quot;ຢູ່ລຸ່ມສະຫຼຸບການສັ່ງຊື້&quot; ສະເໝີເມື່ອໃຊ້ພາສາເຢຍລະມັນສຳລັບ WooCommerce. ປລັກອິນນັ້ນຮຽກຮ້ອງໃຫ້ປຸ່ມສັ່ງຊື້ ແລະ ກ່ອງກາເຄື່ອງໝາຍທາງກົດໝາຍສະແດງຢູ່ລຸ່ມສະຫຼຸບການສັ່ງຊື້.','Edit pickup locations' => 'ແກ້ໄຂສະຖານທີ່ຮັບ','Use local pickup label from WooCommerce settings' => 'ໃຊ້ປ້າຍກຳກັບຮັບເຄື່ອງໃນທ້ອງຖິ່ນຈາກການຕັ້ງຄ່າ WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'ເມື່ອເປີດໃຊ້ງານ, ປ້າຍຊື່ຕົວເລືອກການຮັບສິນຄ້າໃນເວລາຊຳລະເງິນຈະກົງກັບຫົວຂໍ້ຈາກການຕັ້ງຄ່າສະຖານທີ່ຮັບສິນຄ້າຂອງ WooCommerce. ເມື່ອປິດໃຊ້ງານ, ປ້າຍຊື່ຈະໃຊ້ຂໍ້ຄວາມ &quot;ການຮັບສິນຄ້າໃນທ້ອງຖິ່ນ&quot; ທີ່ສາມາດແປໄດ້ຈາກ Fluid Checkout.','Button label for applying coupon codesApply' => 'ສະໝັກ','Checkout step titleContact' => 'ຕິດຕໍ່','Checkout step titleShipping' => 'ການຂົນສົ່ງ','Checkout step titleBilling' => 'ໃບບິນ','Checkout step titlePayment' => 'ການຈ່າຍເງິນ','Checkout substep change link labelChange' => 'ປ່ຽນແປງ','Checkout substep save link labelSave changes' => 'ບັນທຶກການປ່ຽນແປງ','Substep review textNone.' => 'ບໍ່ມີ.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'ບໍ່ໄດ້ເລືອກຮູບ.','Settings sectionCart' => 'ກະຕ່າ','Settings sectionOrder pay' => 'ສັ່ງຈ່າຍ','Settings sectionThank you' => 'ຂອບໃຈ','Settings section titleIntegrations' => 'ການປະສົມປະສານ','Settings section titleLicense keys' => 'ກະແຈໃບອະນຸຍາດ','Captcha positionBefore place order section' => 'ກ່ອນທີ່ຈະວາງພາກສ່ວນຄໍາສັ່ງ','Captcha positionBefore place order button' => 'ກ່ອນທີ່ຈະວາງຄໍາສັ່ງ','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'ປິດ','Log in link label at checkout contact stepLog in' => 'ເຂົ້າສູ່ລະບົບ','Log in separator label at for when guest checkout is disabledOr continue below' => 'ຫຼືສືບຕໍ່ຂ້າງລຸ່ມນີ້','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'ຫຼືສືບຕໍ່ເປັນແຂກ','Clear image selection on admin pages.Remove image' => 'ລຶບຮູບອອກ','shipping packagesShipping %d' => 'ການຂົນສົ່ງ %d','shipping packagesShipping' 